189→    // ── Helper functions ───────────────────────────────────────────────────
190→
191→    /// Fetch, decrypt, and return file content synchronously.
192→    pub fn fetch_and_decrypt_file_content(
193→        fs: &CipherBoxFS,
194→        cid: &str,
195→        encrypted_file_key_hex: &str,
196→        iv_hex: &str,
197→        encryption_mode: &str,
198→    ) -> Result<Vec<u8>, String> {
199→        let api = fs.api.clone();
200→        let private_key = fs.private_key.clone();
201→        let cid_owned = cid.to_string();
202→        let key_hex = encrypted_file_key_hex.to_string();
203→        let iv_hex_owned = iv_hex.to_string();
204→        let mode = encryption_mode.to_string();
205→        let rt = fs.rt.clone();
206→
207→        crate::fuse::block_with_timeout(&rt, async {
208→            let encrypted_bytes =
209→                cipherbox_api_client::ipfs::fetch_content(&api, &cid_owned).await.map_err(|e| e.to_string())?;
210→            let encrypted_file_key = hex::decode(&key_hex)
211→                .map_err(|_| "Invalid file key hex".to_string())?;
212→            let file_key = zeroize::Zeroizing::new(
213→                cipherbox_crypto::ecies::unwrap_key(&encrypted_file_key, &private_key)
214→                    .map_err(|e| format!("File key unwrap failed: {}", e))?,
215→            );
216→            let file_key_arr: [u8; 32] = file_key
217→                .as_slice()
218→                .try_into()
219→                .map_err(|_| "Invalid file key length".to_string())?;
220→
221→            let plaintext = if mode == "CTR" {
222→                let iv = hex::decode(&iv_hex_owned)
223→                    .map_err(|_| "Invalid file IV hex".to_string())?;
224→                let iv_arr: [u8; 16] = iv
225→                    .try_into()
226→                    .map_err(|_| "Invalid CTR IV length (expected 16)".to_string())?;
227→                cipherbox_crypto::aes_ctr::decrypt_aes_ctr(
228→                    &encrypted_bytes,
229→                    &file_key_arr,
230→                    &iv_arr,
231→                )
232→                .map_err(|e| format!("CTR file decryption failed: {}", e))?
233→            } else {
234→                let iv = hex::decode(&iv_hex_owned)
235→                    .map_err(|_| "Invalid file IV hex".to_string())?;
236→                let iv_arr: [u8; 12] = iv
237→                    .try_into()
238→                    .map_err(|_| "Invalid GCM IV length (expected 12)".to_string())?;
239→                cipherbox_crypto::aes::decrypt_aes_gcm(
240→                    &encrypted_bytes,
241→                    &file_key_arr,
242→                    &iv_arr,
243→                )
244→                .map_err(|e| format!("GCM file decryption failed: {}", e))?
245→            };
246→
247→            Ok(plaintext)
248→        })
249→    }
250→
251→    /// Async version of content download + decrypt for background prefetch tasks.
252→    pub async fn fetch_and_decrypt_content_async(
253→        api: &cipherbox_api_client::ApiClient,
254→        cid: &str,
255→        encrypted_file_key_hex: &str,
256→        iv_hex: &str,
257→        encryption_mode: &str,
258→        private_key: &[u8],
259→    ) -> Result<Vec<u8>, String> {
260→        let encrypted_bytes = cipherbox_api_client::ipfs::fetch_content(api, cid).await.map_err(|e| e.to_string())?;
261→        let encrypted_file_key = hex::decode(encrypted_file_key_hex)
262→            .map_err(|_| "Invalid file key hex".to_string())?;
263→        let file_key = zeroize::Zeroizing::new(
264→            cipherbox_crypto::ecies::unwrap_key(&encrypted_file_key, private_key)
265→                .map_err(|e| format!("File key unwrap failed: {}", e))?,
266→        );
267→        let file_key_arr: [u8; 32] = file_key
268→            .as_slice()
269→            .try_into()
270→            .map_err(|_| "Invalid file key length".to_string())?;
271→
272→        let plaintext = if encryption_mode == "CTR" {
273→            let iv =
274→                hex::decode(iv_hex).map_err(|_| "Invalid file IV hex".to_string())?;
275→            let iv_arr: [u8; 16] = iv
276→                .try_into()
277→                .map_err(|_| "Invalid CTR IV length (expected 16)".to_string())?;
278→            cipherbox_crypto::aes_ctr::decrypt_aes_ctr(
279→                &encrypted_bytes,
280→                &file_key_arr,
281→                &iv_arr,
282→            )
283→            .map_err(|e| format!("CTR decryption failed: {}", e))?
284→        } else {
285→            let iv =
286→                hex::decode(iv_hex).map_err(|_| "Invalid file IV hex".to_string())?;
287→            let iv_arr: [u8; 12] = iv
288→                .try_into()
289→                .map_err(|_| "Invalid GCM IV length (expected 12)".to_string())?;
290→            cipherbox_crypto::aes::decrypt_aes_gcm(
291→                &encrypted_bytes,
292→                &file_key_arr,
293→                &iv_arr,
294→            )
295→            .map_err(|e| format!("GCM decryption failed: {}", e))?
296→        };
297→
298→        Ok(plaintext)
299→    }
