 1→//! Top-level SDK client that ties state, sync, and registry together.
 2→//!
 3→//! The `CipherBoxSdkClient` owns the shared `KeyState` and provides
 4→//! methods to start/stop sync and clear key material. The desktop app
 5→//! creates one instance at startup and shares the `state` Arc with
 6→//! FUSE and Tauri command handlers.
 7→
 8→use std::sync::Arc;
 9→use std::time::Duration;
10→
11→use tokio::sync::mpsc;
12→
13→use crate::state::{KeyState, SyncStatus};
14→use crate::sync::SyncDaemon;
15→
16→/// Top-level SDK client.
17→///
18→/// Owns the shared `KeyState` and optionally runs a `SyncDaemon`.
19→/// The desktop app creates one of these, shares `state` with FUSE
20→/// and commands, and bridges sync status updates to the tray icon.
21→pub struct CipherBoxSdkClient {
22→    /// Shared key material state. Passed to SyncDaemon, FUSE, commands.
23→    pub state: Arc<KeyState>,
24→    /// Handle to abort the sync task when stopping.
25→    sync_handle: Option<tokio::task::JoinHandle<()>>,
26→    /// Channel sender to trigger manual sync.
27→    sync_trigger_tx: Option<mpsc::Sender<()>>,
28→}
29→
30→impl CipherBoxSdkClient {
31→    /// Create a new SDK client with the given API base URL.
32→    pub fn new(api_base_url: &str) -> Self {
33→        Self {
34→            state: Arc::new(KeyState::from_url(api_base_url)),
35→            sync_handle: None,
36→            sync_trigger_tx: None,
37→        }
38→    }
39→
40→    /// Create a new SDK client wrapping an existing KeyState.
41→    pub fn from_state(state: Arc<KeyState>) -> Self {
42→        Self {
43→            state,
44→            sync_handle: None,
45→            sync_trigger_tx: None,
46→        }
47→    }
48→
49→    /// Start the background sync daemon.
50→    ///
51→    /// The `status_callback` is invoked on every status change (Idle, Syncing, Error).
52→    /// Returns a `mpsc::Sender<()>` that can be used to trigger manual sync cycles
53→    /// (e.g., from a "Sync Now" tray menu item).
54→    ///
55→    /// If sync is already running, this is a no-op.
56→    pub fn start_sync(
57→        &mut self,
58→        status_callback: Arc<dyn Fn(SyncStatus) + Send + Sync>,
59→        poll_interval: Duration,
60→    ) -> mpsc::Sender<()> {
61→        if self.sync_handle.is_some() {
62→            // Already running -- return existing trigger
63→            return self
64→                .sync_trigger_tx
65→                .clone()
66→                .expect("sync_trigger_tx should exist when sync_handle exists");
67→        }
68→
69→        let (sync_now_tx, sync_now_rx) = mpsc::channel(1);
70→        let state = self.state.clone();
71→
72→        let handle = tokio::spawn(async move {
73→            let mut daemon = SyncDaemon::new(state, status_callback, poll_interval, sync_now_rx);
74→            daemon.run().await;
75→        });
76→
77→        self.sync_handle = Some(handle);
78→        self.sync_trigger_tx = Some(sync_now_tx.clone());
79→        sync_now_tx
80→    }
81→
82→    /// Stop the background sync daemon.
83→    pub fn stop_sync(&mut self) {
84→        if let Some(handle) = self.sync_handle.take() {
85→            handle.abort();
86→        }
87→        self.sync_trigger_tx = None;
88→    }
89→
90→    /// Zero all key material and stop sync.
91→    pub async fn clear(&mut self) {
92→        self.stop_sync();
93→        self.state.clear().await;
94→    }
95→}
