287→/// Heuristic check for network-level errors vs application errors.
288→fn is_network_error(error: &str) -> bool {
289→    let network_patterns = [
290→        "dns error",
291→        "connect error",
292→        "connection refused",
293→        "network unreachable",
294→        "timed out",
295→        "timeout",
296→        "no route to host",
297→        "network is down",
298→        "couldn't resolve host",
299→    ];
300→    let lower = error.to_lowercase();
301→    network_patterns.iter().any(|p| lower.contains(p))
302→}
