  1→//! Encrypted device registry operations.
  2→//!
  3→//! Manages registration of devices in the ECIES-encrypted device registry
  4→//! stored on IPFS/IPNS. The registry enables cross-device awareness.
  5→//!
  6→//! OS-specific operations (keyring, hostname) are NOT here -- the desktop
  7→//! app gathers device info and passes it as parameters.
  8→//!
  9→//! IMPORTANT: Registry operations must NEVER block login.
 10→//! All errors are caught and logged by the caller (tokio::spawn wrapper).
 11→
 12→use std::sync::Arc;
 13→
 14→use base64::Engine;
 15→
 16→use cipherbox_api_client::ApiClient;
 17→use cipherbox_core::registry::{DeviceAuthStatus, DeviceEntry, DevicePlatform, DeviceRegistry};
 18→
 19→use crate::error::SdkError;
 20→
 21→/// Information about a device, gathered by the platform-specific caller.
 22→///
 23→/// The SDK does not gather this information itself -- the desktop app
 24→/// provides it (hostname, platform, version, device model come from
 25→/// platform-specific APIs like keyring and hostname crate).
 26→#[derive(Debug, Clone)]
 27→pub struct DeviceInfo {
 28→    /// Unique device ID (from keyring or ephemeral UUID).
 29→    pub device_id: String,
 30→    /// Human-readable device name (from hostname).
 31→    pub name: String,
 32→    /// Device platform.
 33→    pub platform: DevicePlatform,
 34→    /// App version string (e.g., "0.1.0").
 35→    pub app_version: String,
 36→    /// Device model or OS version string.
 37→    pub device_model: String,
 38→}
 39→
 40→/// Register a device in the encrypted device registry.
 41→///
 42→/// Steps:
 43→/// 1. Derive registry IPNS keypair via HKDF
 44→/// 2. Try to resolve existing registry from IPNS
 45→/// 3. Build device entry from the provided DeviceInfo
 46→/// 4. Update or create registry with the device entry
 47→/// 5. Encrypt registry with user's public key (ECIES)
 48→/// 6. Upload to IPFS and publish IPNS record
 49→///
 50→/// This function should be called via `tokio::spawn` so failures never block login.
 51→pub async fn register_device(
 52→    api: &Arc<ApiClient>,
 53→    private_key: &[u8; 32],
 54→    public_key: &[u8],
 55→    device_info: DeviceInfo,
 56→) -> Result<(), SdkError> {
 57→    // 1. Derive registry IPNS keypair via HKDF
 58→    let (reg_ipns_priv, _reg_ipns_pub, reg_ipns_name) =
 59→        cipherbox_crypto::hkdf::derive_registry_ipns_keypair(private_key)?;
 60→
 61→    // 2. Try to resolve existing registry from IPNS
 62→    let existing_registry =
 63→        match fetch_and_decrypt_registry(api, &reg_ipns_name, private_key).await {
 64→            Ok(reg) => Some(reg),
 65→            Err(_) => None, // No registry exists yet (first device)
 66→        };
 67→
 68→    // 3. Build device entry
 69→    let device_entry = DeviceEntry {
 70→        device_id: device_info.device_id.clone(),
 71→        public_key: hex::encode(public_key),
 72→        name: device_info.name,
 73→        platform: device_info.platform,
 74→        app_version: device_info.app_version,
 75→        device_model: device_info.device_model,
 76→        ip_hash: String::new(), // Not tracked for desktop
 77→        status: if existing_registry.is_none() {
 78→            DeviceAuthStatus::Authorized // First device auto-authorized
 79→        } else {
 80→            DeviceAuthStatus::Pending
 81→        },
 82→        created_at: now_ms(),
 83→        last_seen_at: now_ms(),
 84→        revoked_at: None,
 85→        revoked_by: None,
 86→    };
 87→
 88→    // 4. Build updated registry
 89→    let mut registry = existing_registry.unwrap_or(DeviceRegistry {
 90→        version: "v1".to_string(),
 91→        sequence_number: 0,
 92→        devices: vec![],
 93→    });
 94→
 95→    // Update existing device entry or add new one
 96→    if let Some(existing) = registry
 97→        .devices
 98→        .iter_mut()
 99→        .find(|d| d.device_id == device_info.device_id)
100→    {
101→        existing.last_seen_at = now_ms();
102→        existing.app_version = device_info.device_id.clone(); // Preserve original pattern
103→    } else {
104→        registry.devices.push(device_entry);
105→    }
106→    registry.sequence_number += 1;
107→
108→    // 5. Encrypt registry with user's public key (ECIES)
109→    let registry_json = serde_json::to_vec(&registry).map_err(|e| {
110→        SdkError::RegistryError(format!("Registry serialization failed: {}", e))
111→    })?;
112→    let encrypted = cipherbox_crypto::ecies::wrap_key(&registry_json, public_key)?;
113→
114→    // 6. Upload encrypted registry to IPFS
115→    let cid = cipherbox_api_client::ipfs::upload_content(api, &encrypted)
116→        .await
117→        .map_err(SdkError::Api)?;
118→
119→    // 7. Create and publish IPNS record
120→    let reg_ipns_priv_arr: [u8; 32] = reg_ipns_priv.as_slice().try_into().map_err(|_| {
121→        SdkError::RegistryError("Invalid registry IPNS key length".to_string())
122→    })?;
123→    let value = format!("/ipfs/{}", cid);
124→    let record = cipherbox_core::ipns::create_ipns_record(
125→        &reg_ipns_priv_arr,
126→        &value,
127→        registry.sequence_number,
128→        86_400_000,
129→    )?;
130→    let marshaled = cipherbox_core::ipns::marshal_ipns_record(&record)?;
131→    let record_base64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);
132→
133→    // Device registry publishes do not use conflict detection -- the registry
134→    // IPNS namespace is separate from folder metadata, and the registry write
135→    // is already serialized by the caller.
136→    let publish_req = cipherbox_api_client::IpnsPublishRequest {
137→        ipns_name: reg_ipns_name,
138→        record: record_base64,
139→        metadata_cid: cid,
140→        encrypted_ipns_private_key: None,
141→        key_epoch: None,
142→        expected_sequence_number: None,
143→    };
144→    match cipherbox_api_client::ipns::publish_ipns(api, &publish_req)
145→        .await
146→        .map_err(SdkError::Api)?
147→    {
148→        cipherbox_api_client::PublishResult::Success => {}
149→        cipherbox_api_client::PublishResult::Conflict { .. } => {
150→            log::warn!("Unexpected conflict on device registry publish");
151→        }
152→    }
153→
154→    log::info!(
155→        "Device registered in encrypted registry (device_id: {})",
156→        device_info.device_id
157→    );
158→    Ok(())
159→}
160→
161→/// Fetch and decrypt existing registry from IPNS.
162→async fn fetch_and_decrypt_registry(
163→    api: &ApiClient,
164→    ipns_name: &str,
165→    private_key: &[u8; 32],
166→) -> Result<DeviceRegistry, SdkError> {
167→    let resolve = cipherbox_api_client::ipns::resolve_ipns(api, ipns_name)
168→        .await
169→        .map_err(SdkError::Api)?;
170→    let encrypted = cipherbox_api_client::ipfs::fetch_content(api, &resolve.cid)
171→        .await
172→        .map_err(SdkError::Api)?;
173→    let decrypted = cipherbox_crypto::ecies::unwrap_key(&encrypted, private_key)?;
174→    serde_json::from_slice(&decrypted).map_err(|e| {
175→        SdkError::RegistryError(format!("Registry parse failed: {}", e))
176→    })
177→}
