327→    /// Read file content.
328→    pub fn handle_read(
329→        fs: &mut CipherBoxFS,
330→        ino: u64,
331→        fh: u64,
332→        offset: i64,
333→        size: u32,
334→        reply: ReplyData,
335→    ) {
336→        fs.drain_content_prefetches();
337→
338→        let has_temp = fs.open_files.get(&fh)
339→            .map(|h| h.temp_path.is_some())
340→            .unwrap_or(false);
341→
342→        log::debug!(
343→            "read: ino={} fh={} offset={} size={} has_temp={}",
344→            ino, fh, offset, size, has_temp
345→        );
346→
347→        if has_temp {
348→            if let Some(handle) = fs.open_files.get(&fh) {
349→                match handle.read_at(offset, size) {
350→                    Ok(data) => {
351→                        log::debug!("read: temp file returned {} bytes", data.len());
352→                        reply.data(&data);
353→                        return;
354→                    }
355→                    Err(e) => {
356→                        log::error!("Temp file read failed: {}", e);
357→                        reply.error(libc::EIO);
358→                        return;
359→                    }
360→                }
361→            } else {
362→                reply.error(libc::EBADF);
363→                return;
364→            }
365→        }
366→
367→        let (cid, encrypted_file_key_hex, iv_hex, encryption_mode) = {
368→            match fs.inodes.get(ino) {
369→                Some(inode) => match &inode.kind {
370→                    InodeKind::File {
371→                        cid, encrypted_file_key, iv, encryption_mode, ..
372→                    } => (cid.clone(), encrypted_file_key.clone(), iv.clone(), encryption_mode.clone()),
373→                    _ => {
374→                        reply.error(libc::EISDIR);
375→                        return;
376→                    }
377→                },
378→                None => {
379→                    reply.error(libc::ENOENT);
380→                    return;
381→                }
382→            }
383→        };
384→
385→        if cid.is_empty() {
386→            if let Some(content) = fs.pending_content.get(&ino) {
387→                let start = offset as usize;
388→                if start >= content.len() {
389→                    reply.data(&[]);
390→                } else {
391→                    let end = std::cmp::min(start + size as usize, content.len());
392→                    reply.data(&content[start..end]);
393→                }
394→                return;
395→            }
396→            reply.data(&[]);
397→            return;
398→        }
399→
400→        if let Some(handle) = fs.open_files.get(&fh) {
401→            if let Some(ref content) = handle.cached_content {
402→                let start = offset as usize;
403→                if start >= content.len() {
404→                    reply.data(&[]);
405→                    return;
406→                }
407→                let end = std::cmp::min(start + size as usize, content.len());
408→                reply.data(&content[start..end]);
409→                return;
410→            }
411→        }
412→
413→        if let Some(cached) = fs.content_cache.get(&cid) {
414→            let start = offset as usize;
415→            if start >= cached.len() {
416→                reply.data(&[]);
417→                return;
418→            }
419→            let end = std::cmp::min(start + size as usize, cached.len());
420→            let data_slice = cached[start..end].to_vec();
421→            if let Some(handle) = fs.open_files.get_mut(&fh) {
422→                handle.cached_content = Some(cached.to_vec());
423→            }
424→            reply.data(&data_slice);
425→            return;
426→        }
427→
428→        // Content not in cache -- start prefetch and poll
429→        if !fs.prefetching.contains(&cid) {
430→            let api = fs.api.clone();
431→            let rt = fs.rt.clone();
432→            let tx = fs.content_tx.clone();
433→            let cid_clone = cid.clone();
434→            let efk = encrypted_file_key_hex.clone();
435→            let iv_clone = iv_hex.clone();
436→            let enc_mode = encryption_mode.clone();
437→            let pk = fs.private_key.clone();
438→            fs.prefetching.insert(cid.clone());
439→
440→            rt.spawn(async move {
441→                let result = tokio::time::timeout(
442→                    CONTENT_DOWNLOAD_TIMEOUT,
443→                    fetch_and_decrypt_content_async(
444→                        &api, &cid_clone, &efk, &iv_clone, &enc_mode, &pk,
445→                    ),
446→                )
447→                .await;
448→
449→                match result {
450→                    Ok(Ok(plaintext)) => {
451→                        log::debug!(
452→                            "prefetch(read): cached {} bytes for CID {}",
453→                            plaintext.len(),
454→                            &cid_clone[..cid_clone.len().min(12)]
455→                        );
456→                        let _ = tx.send(crate::PendingContent::Success {
457→                            cid: cid_clone,
458→                            data: plaintext,
459→                        });
460→                    }
461→                    Ok(Err(e)) => {
462→                        log::error!("Read prefetch failed for CID {}: {}", cid_clone, e);
463→                        let _ = tx.send(crate::PendingContent::Failure { cid: cid_clone });
464→                    }
465→                    Err(_) => {
466→                        log::error!("Read prefetch timed out for CID {}", cid_clone);
467→                        let _ = tx.send(crate::PendingContent::Failure { cid: cid_clone });
468→                    }
469→                }
470→            });
471→        }
472→
473→        let poll_start = std::time::Instant::now();
474→        let max_wait = Duration::from_secs(3);
475→        loop {
476→            std::thread::sleep(Duration::from_millis(100));
477→            fs.drain_content_prefetches();
478→            if let Some(cached) = fs.content_cache.get(&cid) {
479→                log::debug!(
480→                    "FUSE read: content ready after {:.1}s for CID {}",
481→                    poll_start.elapsed().as_secs_f64(),
482→                    &cid[..cid.len().min(12)]
483→                );
484→                let start = offset as usize;
485→                if start >= cached.len() {
486→                    reply.data(&[]);
487→                } else {
488→                    let end = std::cmp::min(start + size as usize, cached.len());
489→                    reply.data(&cached[start..end]);
490→                }
491→                return;
492→            }
493→            if poll_start.elapsed() > max_wait {
494→                break;
495→            }
496→        }
497→
498→        reply.error(libc::EIO);
499→    }
500→
501→    /// Release (close) a file handle.
502→    pub fn handle_release(
503→        fs: &mut CipherBoxFS,
504→        ino: u64,
505→        fh: u64,
506→        reply: ReplyEmpty,
507→    ) {
508→        fs.drain_upload_completions();
509→
510→        let handle = fs.open_files.remove(&fh);
511→
512→        if let Some(handle) = handle {
513→            let is_new_file = handle.temp_path.is_some() && {
514→                fs.inodes.get(ino).map(|i| match &i.kind {
515→                    InodeKind::File { cid, .. } => cid.is_empty(),
516→                    _ => false,
517→                }).unwrap_or(false)
518→            };
519→            let needs_upload = handle.temp_path.is_some() && (handle.dirty || is_new_file);
520→            if needs_upload {
521→                log::debug!("release: uploading ino {} (dirty={}, new={})", ino, handle.dirty, is_new_file);
522→
523→                let prepare_result = (|| -> Result<(), String> {
524→                    let plaintext = handle.read_all()?;
525→
526→                    let mut file_key = cipherbox_crypto::utils::generate_file_key();
527→                    let iv = cipherbox_crypto::utils::generate_iv();
528→
529→                    let ciphertext = cipherbox_crypto::aes::encrypt_aes_gcm(
530→                        &plaintext, &file_key, &iv,
531→                    )
532→                    .map_err(|e| format!("File encryption failed: {}", e))?;
533→
534→                    let wrapped_key = cipherbox_crypto::ecies::wrap_key(
535→                        &file_key, &fs.public_key,
536→                    )
537→                    .map_err(|e| format!("Key wrapping failed: {}", e))?;
538→
539→                    cipherbox_crypto::utils::clear_bytes(&mut file_key);
540→
541→                    let (old_file_cid, old_encrypted_key, old_iv, old_size, old_mode,
542→                         existing_versions, file_ipns_private_key, file_meta_ipns_name) =
543→                        fs.inodes.get(ino).map(|inode| {
544→                            match &inode.kind {
545→                                InodeKind::File {
546→                                    cid, encrypted_file_key, iv, size, encryption_mode,
547→                                    versions, file_ipns_private_key, file_meta_ipns_name, ..
548→                                } => (
549→                                    if cid.is_empty() { None } else { Some(cid.clone()) },
550→                                    encrypted_file_key.clone(), iv.clone(), *size,
551→                                    encryption_mode.clone(), versions.clone(),
552→                                    file_ipns_private_key.clone(), file_meta_ipns_name.clone(),
553→                                ),
554→                                _ => (None, String::new(), String::new(), 0, "GCM".to_string(), None, None, None),
555→                            }
556→                        }).unwrap_or((None, String::new(), String::new(), 0, "GCM".to_string(), None, None, None));
557→
558→                    let encrypted_file_key_hex = hex::encode(&wrapped_key);
559→                    let iv_hex = hex::encode(&iv);
560→                    let file_size = plaintext.len() as u64;
561→
562→                    let file_name = fs.inodes.get(ino).map(|i| i.name.clone()).unwrap_or_default();
563→                    let mime_type = mime_from_extension(&file_name);
564→
565→                    let now_ms = SystemTime::now()
566→                        .duration_since(std::time::UNIX_EPOCH)
567→                        .unwrap_or_default()
568→                        .as_millis() as u64;
569→
570→                    let should_version = if let Some(ref versions) = existing_versions {
571→                        if let Some(newest) = versions.first() {
572→                            now_ms.saturating_sub(newest.timestamp) >= VERSION_COOLDOWN_MS
573→                        } else {
574→                            old_file_cid.as_ref().is_some_and(|c| !c.is_empty())
575→                        }
576→                    } else {
577→                        old_file_cid.as_ref().is_some_and(|c| !c.is_empty())
578→                    };
579→
580→                    let (new_versions, pruned_cids) = if should_version {
581→                        if let Some(ref old_c) = old_file_cid {
582→                            if !old_c.is_empty() {
583→                                let version_entry = cipherbox_core::folder::VersionEntry {
584→                                    cid: old_c.clone(),
585→                                    file_key_encrypted: old_encrypted_key.clone(),
586→                                    file_iv: old_iv.clone(),
587→                                    size: old_size,
588→                                    timestamp: now_ms,
589→                                    encryption_mode: old_mode.clone(),
590→                                };
591→                                let mut versions = vec![version_entry];
592→                                versions.extend(existing_versions.unwrap_or_default());
593→                                let pruned: Vec<String> = if versions.len() > MAX_VERSIONS_PER_FILE {
594→                                    versions.split_off(MAX_VERSIONS_PER_FILE).into_iter().map(|v| v.cid).collect()
595→                                } else {
596→                                    vec![]
597→                                };
598→                                if !pruned.is_empty() {
599→                                    log::info!("Pruned {} version(s) for ino {} (exceeded max {})", pruned.len(), ino, MAX_VERSIONS_PER_FILE);
600→                                }
601→                                log::debug!("Created version entry for ino {} (total versions: {})", ino, versions.len());
602→                                (Some(versions), pruned)
603→                            } else {
604→                                (existing_versions, vec![])
605→                            }
606→                        } else {
607→                            (existing_versions, vec![])
608→                        }
609→                    } else {
610→                        if existing_versions.is_some() {
611→                            log::debug!("Version cooldown active for ino {} -- skipping version creation", ino);
612→                        }
613→                        (existing_versions, vec![])
614→                    };
615→
616→                    let versions_for_meta = new_versions.as_ref()
617→                        .filter(|v| !v.is_empty())
618→                        .cloned();
619→
620→                    if let Some(inode) = fs.inodes.get_mut(ino) {
621→                        let cached_hex = match &inode.kind {
622→                            InodeKind::File { file_ipns_key_encrypted_hex, .. } => file_ipns_key_encrypted_hex.clone(),
623→                            _ => None,
624→                        };
625→                        inode.kind = InodeKind::File {
626→                            cid: String::new(),
627→                            encrypted_file_key: encrypted_file_key_hex.clone(),
628→                            iv: iv_hex.clone(),
629→                            size: file_size,
630→                            encryption_mode: "GCM".to_string(),
631→                            file_meta_ipns_name: file_meta_ipns_name.clone(),
632→                            file_meta_resolved: true,
633→                            file_ipns_private_key: file_ipns_private_key.clone(),
634→                            file_ipns_key_encrypted_hex: cached_hex,
635→                            versions: versions_for_meta.clone(),
636→                        };
637→                        inode.attr.size = file_size;
638→                        inode.attr.blocks = (file_size + 511) / 512;
639→                        inode.attr.mtime = SystemTime::now();
640→                    }
641→
642→                    fs.pending_content.insert(ino, plaintext);
643→
644→                    let write_gen = fs.inodes.get(ino)
645→                        .map(|i| i.write_generation)
646→                        .unwrap_or(0);
647→
648→                    let parent_ino = fs.inodes.get(ino)
649→                        .map(|i| i.parent_ino)
650→                        .unwrap_or(ROOT_INO);
651→
652→                    let folder_key_for_file_meta = fs.get_folder_key(parent_ino);
653→
654→                    fs.queue_publish(parent_ino, true);
655→
656→                    let api = fs.api.clone();
657→                    let rt = fs.rt.clone();
658→                    let upload_tx = fs.upload_tx.clone();
659→                    let coordinator = fs.publish_coordinator.clone();
660→
661→                    let file_meta = cipherbox_core::folder::FileMetadata {
662→                        version: "v1".to_string(),
663→                        cid: String::new(),
664→                        file_key_encrypted: encrypted_file_key_hex.clone(),
665→                        file_iv: iv_hex.clone(),
666→                        size: file_size,
667→                        mime_type,
668→                        encryption_mode: "GCM".to_string(),
669→                        created_at: now_ms,
670→                        modified_at: now_ms,
671→                        versions: versions_for_meta,
672→                    };
673→
674→                    std::thread::spawn(move || {
675→                        let result = rt.block_on(async {
676→                            let file_cid = cipherbox_api_client::ipfs::upload_content(
677→                                &api, &ciphertext,
678→                            ).await.map_err(|e| format!("{}", e))?;
679→
680→                            log::info!("File uploaded: ino {} -> CID {}", ino, file_cid);
681→
682→                            let _ = upload_tx.send(crate::UploadComplete {
683→                                ino,
684→                                new_cid: file_cid.clone(),
685→                                parent_ino,
686→                                old_file_cid,
687→                                pruned_cids,
688→                                write_generation: write_gen,
689→                            });
690→
691→                            if let (Some(ipns_key), Some(ipns_name), Some(folder_key)) =
692→                                (&file_ipns_private_key, &file_meta_ipns_name, &folder_key_for_file_meta)
693→                            {
694→                                let mut file_meta_with_cid = file_meta;
695→                                file_meta_with_cid.cid = file_cid;
696→
697→                                if let Err(e) = publish_file_metadata(
698→                                    &api, &file_meta_with_cid, folder_key, ipns_key, ipns_name, &coordinator,
699→                                ).await {
700→                                    log::warn!("Per-file IPNS publish failed for ino {}: {}", ino, e);
701→                                }
702→                            } else {
703→                                log::warn!(
704→                                    "release: skipping per-file IPNS publish for ino {} (missing key/name/folder_key)",
705→                                    ino
706→                                );
707→                            }
708→
709→                            Ok::<(), String>(())
710→                        });
711→
712→                        if let Err(e) = result {
713→                            log::error!("Background upload failed for ino {}: {}", ino, e);
714→                        }
715→                    });
716→
717→                    Ok(())
718→                })();
719→
720→                if let Err(e) = prepare_result {
721→                    log::error!("File upload preparation failed for ino {}: {}", ino, e);
722→                }
723→
724→                handle.cleanup();
725→            }
726→        }
727→
728→        reply.ok();
729→    }
