  1→//! Open file handle with temp file write buffering.
  2→//!
  3→//! Implements the "temp-file commit model": writes buffer to a local temp file,
  4→//! then encrypt + upload on file close (release). This avoids uploading on
  5→//! every write() call and ensures atomic file content updates.
  6→
  7→use std::fs;
  8→use std::io::{Read, Seek, SeekFrom, Write};
  9→use std::path::{Path, PathBuf};
 10→use std::time::{SystemTime, UNIX_EPOCH};
 11→use zeroize::Zeroize;
 12→
 13→/// Platform-agnostic access mode for open file handles.
 14→/// Replaces POSIX O_RDONLY / O_WRONLY / O_RDWR flags that depend on libc.
 15→#[derive(Debug, Clone, Copy, PartialEq)]
 16→pub enum AccessMode {
 17→    ReadOnly,
 18→    WriteOnly,
 19→    ReadWrite,
 20→}
 21→
 22→/// Open file handle tracking active reads and writes.
 23→///
 24→/// For read-only opens, only `cached_content` is populated.
 25→/// For writable opens, a temp file is created for buffering writes.
 26→/// On release, if dirty, the temp file content is encrypted and uploaded.
 27→pub struct OpenFileHandle {
 28→    /// Inode number of the open file.
 29→    pub ino: u64,
 30→    /// Platform-agnostic access mode.
 31→    pub access_mode: AccessMode,
 32→    /// Path to temp file used for write buffering (None for read-only opens).
 33→    pub temp_path: Option<PathBuf>,
 34→    /// Whether the file has been modified since open.
 35→    pub dirty: bool,
 36→    /// Pre-fetched decrypted content for reads (populated on first read).
 37→    pub cached_content: Option<Vec<u8>>,
 38→    /// Original file size before modifications.
 39→    pub original_size: u64,
 40→}
 41→
 42→impl OpenFileHandle {
 43→    /// Create a read-only file handle. No temp file, not dirty.
 44→    pub fn new_read(ino: u64) -> Self {
 45→        Self {
 46→            ino,
 47→            access_mode: AccessMode::ReadOnly,
 48→            temp_path: None,
 49→            dirty: false,
 50→            cached_content: None,
 51→            original_size: 0,
 52→        }
 53→    }
 54→
 55→    /// Create a writable file handle with a temp file.
 56→    ///
 57→    /// If `existing_content` is provided (editing an existing file),
 58→    /// the temp file is pre-populated with the decrypted content.
 59→    pub fn new_write(
 60→        ino: u64,
 61→        temp_dir: &Path,
 62→        existing_content: Option<&[u8]>,
 63→    ) -> Result<Self, String> {
 64→        // Ensure temp directory exists
 65→        fs::create_dir_all(temp_dir)
 66→            .map_err(|e| format!("Failed to create temp dir: {}", e))?;
 67→
 68→        // Generate unique temp file name
 69→        let timestamp = SystemTime::now()
 70→            .duration_since(UNIX_EPOCH)
 71→            .unwrap_or_default()
 72→            .as_nanos();
 73→        let temp_path = temp_dir.join(format!("cb-write-{}-{}", ino, timestamp));
 74→
 75→        // Create temp file and optionally pre-populate
 76→        let original_size = if let Some(content) = existing_content {
 77→            fs::write(&temp_path, content)
 78→                .map_err(|e| format!("Failed to write temp file: {}", e))?;
 79→            content.len() as u64
 80→        } else {
 81→            // Create empty temp file
 82→            fs::File::create(&temp_path)
 83→                .map_err(|e| format!("Failed to create temp file: {}", e))?;
 84→            0
 85→        };
 86→
 87→        // Restrict temp file permissions to owner-only
 88→        #[cfg(unix)]
 89→        {
 90→            use std::os::unix::fs::PermissionsExt;
 91→            let _ = fs::set_permissions(&temp_path, fs::Permissions::from_mode(0o600));
 92→        }
 93→
 94→        Ok(Self {
 95→            ino,
 96→            access_mode: AccessMode::ReadWrite,
 97→            temp_path: Some(temp_path),
 98→            dirty: false,
 99→            cached_content: None,
100→            original_size,
101→        })
102→    }
103→
104→    /// Write data to the temp file at the given offset. Marks the handle as dirty.
105→    pub fn write_at(&mut self, offset: i64, data: &[u8]) -> Result<usize, String> {
106→        let temp_path = self
107→            .temp_path
108→            .as_ref()
109→            .ok_or("No temp file for write")?;
110→
111→        let mut file = fs::OpenOptions::new()
112→            .write(true)
113→            .open(temp_path)
114→            .map_err(|e| format!("Failed to open temp file for write: {}", e))?;
115→
116→        file.seek(SeekFrom::Start(offset as u64))
117→            .map_err(|e| format!("Failed to seek temp file: {}", e))?;
118→
119→        file.write_all(data)
120→            .map_err(|e| format!("Failed to write to temp file: {}", e))?;
121→
122→        self.dirty = true;
123→        Ok(data.len())
124→    }
125→
126→    /// Read data from the temp file at the given offset.
127→    ///
128→    /// Used for files opened for write that also need reading (O_RDWR).
129→    pub fn read_at(&self, offset: i64, size: u32) -> Result<Vec<u8>, String> {
130→        let temp_path = self
131→            .temp_path
132→            .as_ref()
133→            .ok_or("No temp file for read")?;
134→
135→        let mut file = fs::OpenOptions::new()
136→            .read(true)
137→            .open(temp_path)
138→            .map_err(|e| format!("Failed to open temp file for read: {}", e))?;
139→
140→        file.seek(SeekFrom::Start(offset as u64))
141→            .map_err(|e| format!("Failed to seek temp file: {}", e))?;
142→
143→        let mut buf = vec![0u8; size as usize];
144→        let bytes_read = file
145→            .read(&mut buf)
146→            .map_err(|e| format!("Failed to read from temp file: {}", e))?;
147→
148→        buf.truncate(bytes_read);
149→        Ok(buf)
150→    }
151→
152→    /// Get the current size of the temp file.
153→    pub fn get_size(&self) -> Result<u64, String> {
154→        let temp_path = self
155→            .temp_path
156→            .as_ref()
157→            .ok_or("No temp file")?;
158→
159→        let metadata = fs::metadata(temp_path)
160→            .map_err(|e| format!("Failed to get temp file metadata: {}", e))?;
161→
162→        Ok(metadata.len())
163→    }
164→
165→    /// Read the entire temp file contents (used for encrypt + upload on close).
166→    pub fn read_all(&self) -> Result<Vec<u8>, String> {
167→        let temp_path = self
168→            .temp_path
169→            .as_ref()
170→            .ok_or("No temp file for read_all")?;
171→
172→        fs::read(temp_path).map_err(|e| format!("Failed to read temp file: {}", e))
173→    }
174→
175→    /// Truncate the temp file to the given size.
176→    pub fn truncate(&self, size: u64) -> Result<(), String> {
177→        let temp_path = self
178→            .temp_path
179→            .as_ref()
180→            .ok_or("No temp file for truncate")?;
181→
182→        let file = fs::OpenOptions::new()
183→            .write(true)
184→            .open(temp_path)
185→            .map_err(|e| format!("Failed to open temp file for truncate: {}", e))?;
186→
187→        file.set_len(size)
188→            .map_err(|e| format!("Failed to truncate temp file: {}", e))
189→    }
190→
191→    /// Delete the temp file. Called after upload or on error.
192→    /// Overwrites file content with zeros before deletion for defense-in-depth.
193→    pub fn cleanup(&self) {
194→        if let Some(ref temp_path) = self.temp_path {
195→            if temp_path.exists() {
196→                // Overwrite with zeros before deletion
197→                if let Ok(size) = fs::metadata(temp_path).map(|m| m.len()) {
198→                    if size > 0 {
199→                        if let Ok(mut file) = fs::OpenOptions::new().write(true).open(temp_path) {
200→                            let zeros = vec![0u8; std::cmp::min(size as usize, 64 * 1024)];
201→                            let mut remaining = size;
202→                            while remaining > 0 {
203→                                let chunk = std::cmp::min(remaining, zeros.len() as u64);
204→                                let _ = std::io::Write::write_all(&mut file, &zeros[..chunk as usize]);
205→                                remaining -= chunk;
206→                            }
207→                            let _ = file.sync_all();
208→                        }
209→                    }
210→                }
211→                if let Err(e) = fs::remove_file(temp_path) {
212→                    log::warn!("Failed to cleanup temp file {:?}: {}", temp_path, e);
213→                }
214→            }
215→        }
216→    }
217→}
218→
219→impl Drop for OpenFileHandle {
220→    fn drop(&mut self) {
221→        // Zeroize any cached plaintext content before freeing
222→        if let Some(ref mut content) = self.cached_content {
223→            content.zeroize();
224→        }
225→        self.cleanup();
226→    }
227→}
