269→    /// Remove an inode from the table and clean up the name lookup.
270→    #[allow(dead_code)]
271→    #[cfg(any(feature = "fuse", feature = "winfsp"))]
272→    pub fn remove(&mut self, ino: u64) {
273→        if let Some(data) = self.inodes.remove(&ino) {
274→            self.name_to_ino
275→                .remove(&(data.parent_ino, normalize_name(&data.name)));
276→            // Also remove from parent's children list
277→            if let Some(parent) = self.inodes.get_mut(&data.parent_ino) {
278→                if let Some(ref mut children) = parent.children {
279→                    children.retain(|&c| c != ino);
280→                }
281→            }
282→        }
283→    }
