285→    /// Populate a folder's children from decrypted v2 folder metadata (per-file IPNS pointers).
286→    ///
287→    /// For each child:
288→    /// - **Subfolder:** Decrypts `folder_key_encrypted` and `ipns_private_key_encrypted`
289→    ///   using the user's secp256k1 private key (ECIES unwrap).
290→    /// - **FilePointer:** Creates a placeholder inode with fileMetaIpnsName set.
291→    ///   The file's CID/key/IV/size are NOT yet known -- they require IPNS resolution.
292→    ///   Callers must resolve FilePointers before the first READDIR (NFS stability).
293→    ///
294→    /// IMPORTANT: Reuses existing inode numbers for children matching by name (NFS stability).
295→    ///
296→    /// When `merge_only` is true (background refresh), existing children not
297→    /// present in the remote metadata are preserved. This prevents background
298→    /// IPNS refreshes from wiping files whose publish hasn't propagated yet.
299→    /// When false (initial mount), children not in metadata are removed.
300→    #[cfg(any(feature = "fuse", feature = "winfsp"))]
301→    pub fn populate_folder(
302→        &mut self,
303→        parent_ino: u64,
304→        metadata: &FolderMetadata,
305→        private_key: &[u8],
306→        public_key: &[u8],
307→        merge_only: bool,
308→    ) -> Result<(), String> {
309→        // Build set of new child names for detecting removals
310→        let new_names: std::collections::HashSet<String> = metadata.children.iter().map(|c| {
311→            match c {
312→                FolderChild::Folder(f) => f.name.clone(),
313→                FolderChild::File(f) => f.name.clone(),
314→            }
315→        }).collect();
316→
317→        // Get existing children to detect removals
318→        let old_child_inos: Vec<u64> = self.inodes.get(&parent_ino)
319→            .and_then(|p| p.children.as_ref())
320→            .cloned()
321→            .unwrap_or_default();
322→
323→        // Remove children not in remote metadata (only during initial mount, not refresh)
324→        if !merge_only {
325→            for old_ino in &old_child_inos {
326→                if let Some(old_child) = self.inodes.get(old_ino) {
327→                    if !new_names.contains(&old_child.name) {
328→                        let name = old_child.name.clone();
329→                        self.inodes.remove(old_ino);
330→                        self.name_to_ino.remove(&(parent_ino, normalize_name(&name)));
331→                    }
332→                }
333→            }
334→        }
335→
336→        let mut child_inos = Vec::new();
337→
338→        for child in &metadata.children {
339→            match child {
340→                FolderChild::Folder(folder) => {
341→                    // Reuse existing ino if child with same name exists
342→                    let existing_ino = self.find_child(parent_ino, &folder.name);
343→                    let ino = existing_ino.unwrap_or_else(|| self.allocate_ino());
344→
345→                    // Decrypt folder key (ECIES unwrap)
346→                    let encrypted_folder_key_bytes =
347→                        hex::decode(&folder.folder_key_encrypted)
348→                            .map_err(|_| format!(
349→                                "Invalid folderKeyEncrypted hex for folder '{}'",
350→                                folder.name
351→                            ))?;
352→                    let folder_key = Zeroizing::new(
353→                        cipherbox_crypto::ecies::unwrap_key(&encrypted_folder_key_bytes, private_key)
354→                            .map_err(|e| format!(
355→                                "Failed to decrypt folder key for '{}': {}",
356→                                folder.name, e
357→                            ))?
358→                    );
359→
360→                    // Decrypt IPNS private key (ECIES unwrap)
361→                    let encrypted_ipns_key_bytes =
362→                        hex::decode(&folder.ipns_private_key_encrypted)
363→                            .map_err(|_| format!(
364→                                "Invalid ipnsPrivateKeyEncrypted hex for folder '{}'",
365→                                folder.name
366→                            ))?;
367→                    let ipns_private_key = Zeroizing::new(
368→                        cipherbox_crypto::ecies::unwrap_key(&encrypted_ipns_key_bytes, private_key)
369→                            .map_err(|e| format!(
370→                                "Failed to decrypt IPNS private key for '{}': {}",
371→                                folder.name, e
372→                            ))?
373→                    );
374→
375→                    let created = UNIX_EPOCH + Duration::from_millis(folder.created_at);
376→                    let modified = UNIX_EPOCH + Duration::from_millis(folder.modified_at);
377→
378→                    // Preserve existing children list and loaded state for existing folders
379→                    let (existing_children, was_loaded) = if existing_ino.is_some() {
380→                        let old = self.inodes.get(&ino);
381→                        let ch = old.and_then(|o| o.children.clone());
382→                        let loaded = old.map(|o| matches!(&o.kind, InodeKind::Folder { children_loaded: true, .. })).unwrap_or(false);
383→                        (ch, loaded)
384→                    } else {
385→                        (Some(vec![]), false)
386→                    };
387→
388→                    let attr = FileAttrs {
389→                        ino,
390→                        size: 0,
391→                        blocks: 0,
392→                        atime: modified,
393→                        mtime: modified,
394→                        ctime: modified,
395→                        crtime: created,
396→                        is_dir: true,
397→                        perm: 0o755,
398→                        nlink: 2,
399→                    };
400→
401→                    let inode = InodeData {
402→                        ino,
403→                        parent_ino,
404→                        name: folder.name.clone(),
405→                        kind: InodeKind::Folder {
406→                            ipns_name: folder.ipns_name.clone(),
407→                            encrypted_folder_key: folder.folder_key_encrypted.clone(),
408→                            folder_key,
409→                            ipns_private_key: Some(ipns_private_key),
410→                            children_loaded: was_loaded,
411→                        },
412→                        attr,
413→                        children: existing_children,
414→                        write_generation: 0,
415→                    };
416→
417→                    self.insert(inode);
418→                    child_inos.push(ino);
419→                }
420→                FolderChild::File(file_pointer) => {
421→                    // Reuse existing ino if child with same name exists
422→                    let existing_ino = self.find_child(parent_ino, &file_pointer.name);
423→                    let ino = existing_ino.unwrap_or_else(|| self.allocate_ino());
424→
425→                    let created = UNIX_EPOCH + Duration::from_millis(file_pointer.created_at);
426→                    let modified = UNIX_EPOCH + Duration::from_millis(file_pointer.modified_at);
427→
428→                    // Check if the existing inode already has resolved metadata
429→                    let (_resolved, existing_kind) = if let Some(existing) = existing_ino
430→                        .and_then(|ino| self.inodes.get(&ino))
431→                    {
432→                        match &existing.kind {
433→                            InodeKind::File { file_meta_resolved: true, .. } => {
434→                                (true, Some(existing.kind.clone()))
435→                            }
436→                            _ => (false, None),
437→                        }
438→                    } else {
439→                        (false, None)
440→                    };
441→
442→                    // If already resolved from a previous population cycle, keep existing data
443→                    let kind = if let Some(existing_kind) = existing_kind {
444→                        existing_kind
445→                    } else {
446→                        // Decrypt file IPNS private key from FilePointer if available,
447→                        // falling back to HKDF derivation for legacy files only.
448→                        let has_encrypted_key = file_pointer.ipns_private_key_encrypted.is_some();
449→                        let file_ipns_key = if let Some(ref encrypted_hex) = file_pointer.ipns_private_key_encrypted {
450→                            match hex::decode(encrypted_hex) {
451→                                Ok(encrypted_bytes) => {
452→                                    match cipherbox_crypto::ecies::unwrap_key(&encrypted_bytes, private_key) {
453→                                        Ok(key) => Some(Zeroizing::new(key)),
454→                                        Err(e) => {
455→                                            log::error!(
456→                                                "File '{}': failed to decrypt ipnsPrivateKeyEncrypted: {}. Cannot use HKDF for random-key files.",
457→                                                file_pointer.name, e
458→                                            );
459→                                            None
460→                                        }
461→                                    }
462→                                }
463→                                Err(e) => {
464→                                    log::error!(
465→                                        "File '{}': invalid ipnsPrivateKeyEncrypted hex: {}. Cannot use HKDF for random-key files.",
466→                                        file_pointer.name, e
467→                                    );
468→                                    None
469→                                }
470→                            }
471→                        } else {
472→                            None
473→                        };
474→
475→                        // HKDF fallback ONLY for legacy FilePointers (no encrypted key present).
476→                        // If ipnsPrivateKeyEncrypted was present but decryption failed, HKDF would
477→                        // produce a key that doesn't match the file's random IPNS name.
478→                        let file_ipns_key = if file_ipns_key.is_some() {
479→                            file_ipns_key
480→                        } else if !has_encrypted_key {
481→                            if let Ok(pk_arr) = <[u8; 32]>::try_from(private_key) {
482→                                match cipherbox_crypto::hkdf::derive_file_ipns_keypair(&pk_arr, &file_pointer.id) {
483→                                    Ok((derived_key, _, _)) => {
484→                                        log::debug!(
485→                                            "File '{}': derived IPNS key via HKDF fallback (legacy file).",
486→                                            file_pointer.name
487→                                        );
488→                                        Some(derived_key)
489→                                    }
490→                                    Err(e) => {
491→                                        log::warn!(
492→                                            "File '{}': HKDF fallback also failed: {}. File IPNS updates will be unavailable.",
493→                                            file_pointer.name, e
494→                                        );
495→                                        None
496→                                    }
497→                                }
498→                            } else {
499→                                log::warn!(
500→                                    "File '{}': private key is not 32 bytes, cannot derive HKDF fallback.",
501→                                    file_pointer.name
502→                                );
503→                                None
504→                            }
505→                        } else {
506→                            None
507→                        };
508→
509→                        // Cache the ECIES-wrapped hex for build_folder_metadata.
510→                        // For legacy files (HKDF fallback), wrap the derived key now so
511→                        // the next folder publish persists it -- lazy migration to random keys.
512→                        let cached_encrypted_hex = if file_pointer.ipns_private_key_encrypted.is_some() {
513→                            file_pointer.ipns_private_key_encrypted.clone()
514→                        } else if let Some(ref key) = file_ipns_key {
515→                            match cipherbox_crypto::ecies::wrap_key(key, public_key) {
516→                                Ok(wrapped) => {
517→                                    log::info!(
518→                                        "File '{}': wrapped HKDF-derived IPNS key for lazy migration.",
519→                                        file_pointer.name
520→                                    );
521→                                    Some(hex::encode(&wrapped))
522→                                }
523→                                Err(e) => {
524→                                    log::warn!(
525→                                        "File '{}': failed to wrap HKDF key for migration: {}. Will re-wrap on publish.",
526→                                        file_pointer.name, e
527→                                    );
528→                                    None
529→                                }
530→                            }
531→                        } else {
532→                            None
533→                        };
534→
535→                        InodeKind::File {
536→                            cid: String::new(),
537→                            encrypted_file_key: String::new(),
538→                            iv: String::new(),
539→                            size: 0,
540→                            encryption_mode: "GCM".to_string(),
541→                            file_meta_ipns_name: Some(file_pointer.file_meta_ipns_name.clone()),
542→                            file_meta_resolved: false,
543→                            file_ipns_private_key: file_ipns_key,
544→                            file_ipns_key_encrypted_hex: cached_encrypted_hex,
545→                            versions: None,
546→                        }
547→                    };
548→
549→                    // Use the existing size if resolved, otherwise 0
550→                    let display_size = match &kind {
551→                        InodeKind::File { size, .. } => *size,
552→                        _ => 0,
553→                    };
554→
555→                    let attr = FileAttrs {
556→                        ino,
557→                        size: display_size,
558→                        blocks: (display_size + 511) / 512,
559→                        atime: modified,
560→                        mtime: modified,
561→                        ctime: modified,
562→                        crtime: created,
563→                        is_dir: false,
564→                        perm: 0o644,
565→                        nlink: 1,
566→                    };
567→
568→                    let inode = InodeData {
569→                        ino,
570→                        parent_ino,
571→                        name: file_pointer.name.clone(),
572→                        kind,
573→                        attr,
574→                        children: None,
575→                        write_generation: 0,
576→                    };
577→
578→                    self.insert(inode);
579→                    child_inos.push(ino);
580→                }
581→            }
582→        }
583→
584→        // In merge_only mode, preserve existing children not in remote metadata
585→        if merge_only {
586→            for &old_ino in &old_child_inos {
587→                if !child_inos.contains(&old_ino) {
588→                    child_inos.push(old_ino);
589→                }
590→            }
591→        }
592→
593→        // Set parent's children list
594→        if let Some(parent) = self.inodes.get_mut(&parent_ino) {
595→            let old_children = parent.children.as_ref().cloned().unwrap_or_default();
596→            let children_changed = old_children.len() != child_inos.len()
597→                || old_children != child_inos;
598→            if children_changed {
599→                let now = SystemTime::now();
600→                parent.attr.mtime = now;
601→                parent.attr.ctime = now;
602→            }
603→
604→            parent.children = Some(child_inos);
605→            match &mut parent.kind {
606→                InodeKind::Root { .. } => {}
607→                InodeKind::Folder { children_loaded, .. } => {
608→                    *children_loaded = true;
609→                }
610→                _ => {}
611→            }
612→        }
613→
614→        Ok(())
615→    }
