617→    /// Update a FilePointer inode with resolved metadata (CID, key, IV, size, mode, versions).
618→    ///
619→    /// Called after per-file IPNS resolution succeeds. Updates the inode in place.
620→    #[cfg(any(feature = "fuse", feature = "winfsp"))]
621→    pub fn resolve_file_pointer(
622→        &mut self,
623→        ino: u64,
624→        cid: String,
625→        encrypted_file_key: String,
626→        iv: String,
627→        size: u64,
628→        encryption_mode: String,
629→        versions: Option<Vec<cipherbox_core::folder::VersionEntry>>,
630→    ) {
631→        if let Some(inode) = self.inodes.get_mut(&ino) {
632→            inode.kind = InodeKind::File {
633→                cid,
634→                encrypted_file_key,
635→                iv,
636→                size,
637→                encryption_mode,
638→                file_meta_ipns_name: match &inode.kind {
639→                    InodeKind::File { file_meta_ipns_name, .. } => file_meta_ipns_name.clone(),
640→                    _ => None,
641→                },
642→                file_meta_resolved: true,
643→                file_ipns_private_key: match &inode.kind {
644→                    InodeKind::File { file_ipns_private_key, .. } => file_ipns_private_key.clone(),
645→                    _ => None,
646→                },
647→                file_ipns_key_encrypted_hex: match &inode.kind {
648→                    InodeKind::File { file_ipns_key_encrypted_hex, .. } => file_ipns_key_encrypted_hex.clone(),
649→                    _ => None,
650→                },
651→                versions,
652→            };
653→            // Update attr size for GETATTR/READDIR
654→            inode.attr.size = size;
655→            inode.attr.blocks = (size + 511) / 512;
656→        }
657→    }
