400→    /// Create a new directory.
401→    pub fn handle_mkdir(
402→        fs: &mut CipherBoxFS,
403→        parent: u64,
404→        name: &OsStr,
405→        reply: ReplyEntry,
406→    ) {
407→        let name_str = match name.to_str() {
408→            Some(n) => n,
409→            None => {
410→                reply.error(libc::EINVAL);
411→                return;
412→            }
413→        };
414→
415→        if is_platform_special(name_str) {
416→            reply.error(libc::EACCES);
417→            return;
418→        }
419→
420→        let parent_exists = fs.inodes.get(parent).map(|inode| {
421→            matches!(inode.kind, InodeKind::Root { .. } | InodeKind::Folder { .. })
422→        });
423→        if parent_exists != Some(true) {
424→            reply.error(libc::ENOENT);
425→            return;
426→        }
427→
428→        log::debug!("mkdir: {} in parent {}", name_str, parent);
429→
430→        let result = (|| -> Result<fuser::FileAttr, String> {
431→            let folder_key = cipherbox_crypto::utils::generate_file_key();
432→
433→            let (ipns_public_key, ipns_private_key) =
434→                cipherbox_crypto::generate_ed25519_keypair();
435→
436→            let ipns_pub_arr: [u8; 32] = ipns_public_key.clone().try_into()
437→                .map_err(|_| "Invalid IPNS public key length".to_string())?;
438→            let ipns_name = cipherbox_core::ipns::derive_ipns_name(&ipns_pub_arr)
439→                .map_err(|e| format!("Failed to derive IPNS name: {}", e))?;
440→
441→            let wrapped_folder_key = cipherbox_crypto::wrap_key(
442→                &folder_key, &fs.public_key,
443→            )
444→            .map_err(|e| format!("Folder key wrapping failed: {}", e))?;
445→            let encrypted_folder_key_hex = hex::encode(&wrapped_folder_key);
446→
447→            let ino = fs.inodes.allocate_ino();
448→            let now = SystemTime::now();
449→
450→            let attr = FileAttrs {
451→                ino,
452→                size: 0,
453→                blocks: 0,
454→                atime: now,
455→                mtime: now,
456→                ctime: now,
457→                crtime: now,
458→                is_dir: true,
459→                perm: 0o755,
460→                nlink: 2,
461→            };
462→            let fuse_attr = attr.to_fuse_attr(current_uid(), current_gid());
463→
464→            let inode = InodeData {
465→                ino,
466→                parent_ino: parent,
467→                name: name_str.to_string(),
468→                kind: InodeKind::Folder {
469→                    ipns_name: ipns_name.clone(),
470→                    encrypted_folder_key: encrypted_folder_key_hex,
471→                    folder_key: zeroize::Zeroizing::new(folder_key.to_vec()),
472→                    ipns_private_key: Some(zeroize::Zeroizing::new(ipns_private_key.clone())),
473→                    children_loaded: true,
474→                },
475→                attr,
476→                children: Some(vec![]),
477→                write_generation: 0,
478→            };
479→
480→            fs.inodes.insert(inode);
481→
482→            if let Some(parent_inode) = fs.inodes.get_mut(parent) {
483→                if let Some(ref mut children) = parent_inode.children {
484→                    children.push(ino);
485→                }
486→                parent_inode.attr.mtime = SystemTime::now();
487→                parent_inode.attr.ctime = SystemTime::now();
488→            }
489→
490→            let metadata = cipherbox_core::folder::FolderMetadata {
491→                version: "v2".to_string(),
492→                children: vec![],
493→            };
494→
495→            let json_bytes = crate::encrypt_metadata_to_json(
496→                &metadata, &folder_key,
497→            )?;
498→
499→            let encrypted_ipns_for_tee = if let Some(ref tee_key) = fs.tee_public_key {
500→                let wrapped = cipherbox_crypto::wrap_key(&ipns_private_key, tee_key)
501→                    .map_err(|e| format!("TEE key wrapping failed: {}", e))?;
502→                Some(hex::encode(&wrapped))
503→            } else {
504→                None
505→            };
506→            let tee_key_epoch = fs.tee_key_epoch;
507→
508→            let (parent_metadata, parent_folder_key, parent_ipns_key, parent_ipns_name, parent_old_cid) =
509→                fs.build_folder_metadata(parent)?;
510→
511→            let api = fs.api.clone();
512→            let rt = fs.rt.clone();
513→            let ipns_name_clone = ipns_name.clone();
514→            let coordinator = fs.publish_coordinator.clone();
515→
516→            std::thread::spawn(move || {
517→                let result = rt.block_on(async {
518→                    let initial_cid = cipherbox_api_client::ipfs::upload_content(
519→                        &api, &json_bytes,
520→                    ).await.map_err(|e| format!("{}", e))?;
521→
522→                    let ipns_key_arr: [u8; 32] = ipns_private_key.try_into()
523→                        .map_err(|_| "Invalid IPNS key length".to_string())?;
524→                    let value = format!("/ipfs/{}", initial_cid);
525→                    let record = cipherbox_core::ipns::create_ipns_record(
526→                        &ipns_key_arr, &value, 0, 86_400_000,
527→                    ).map_err(|e| format!("IPNS record creation failed: {}", e))?;
528→                    let marshaled = cipherbox_core::ipns::marshal_ipns_record(&record)
529→                        .map_err(|e| format!("IPNS marshal failed: {}", e))?;
530→
531→                    use base64::Engine;
532→                    let record_b64 = base64::engine::general_purpose::STANDARD
533→                        .encode(&marshaled);
534→
535→                    // New folder initial publish: sequence 0, no conflict check needed
536→                    let req = cipherbox_api_client::IpnsPublishRequest {
537→                        ipns_name: ipns_name_clone.clone(),
538→                        record: record_b64,
539→                        metadata_cid: initial_cid,
540→                        encrypted_ipns_private_key: encrypted_ipns_for_tee,
541→                        key_epoch: tee_key_epoch,
542→                        expected_sequence_number: None,
543→                    };
544→                    match cipherbox_api_client::ipns::publish_ipns(&api, &req).await.map_err(|e| format!("{}", e))? {
545→                        cipherbox_api_client::PublishResult::Success => {
546→                            coordinator.record_publish(&ipns_name_clone, 0);
547→                            log::info!("New folder IPNS published: {}", ipns_name_clone);
548→                        }
549→                        cipherbox_api_client::PublishResult::Conflict { .. } => {
550→                            // Sequence 0 should never conflict -- log and continue
551→                            log::warn!("Unexpected conflict on new folder IPNS publish for {}", ipns_name_clone);
552→                        }
553→                    }
554→
555→                    let lock = coordinator.get_lock(&parent_ipns_name);
556→                    let _guard = lock.lock().await;
557→
558→                    let parent_json = crate::encrypt_metadata_to_json(
559→                        &parent_metadata, &parent_folder_key,
560→                    )?;
561→
562→                    let seq = coordinator.resolve_sequence(&api, &parent_ipns_name).await?;
563→
564→                    let parent_meta_cid = cipherbox_api_client::ipfs::upload_content(
565→                        &api, &parent_json,
566→                    ).await.map_err(|e| format!("{}", e))?;
567→
568→                    let parent_key_arr: [u8; 32] = parent_ipns_key.try_into()
569→                        .map_err(|_| "Invalid parent IPNS key length".to_string())?;
570→                    let new_seq = seq + 1;
571→                    let parent_value = format!("/ipfs/{}", parent_meta_cid);
572→                    let parent_record = cipherbox_core::ipns::create_ipns_record(
573→                        &parent_key_arr, &parent_value, new_seq, 86_400_000,
574→                    ).map_err(|e| format!("Parent IPNS record failed: {}", e))?;
575→                    let parent_marshaled = cipherbox_core::ipns::marshal_ipns_record(
576→                        &parent_record,
577→                    ).map_err(|e| format!("Parent IPNS marshal failed: {}", e))?;
578→                    let parent_record_b64 = base64::engine::general_purpose::STANDARD
579→                        .encode(&parent_marshaled);
580→
581→                    // Parent folder publish after mkdir includes conflict detection.
582→                    // On conflict, log a warning -- the debounced publish queue will
583→                    // retry the parent metadata on the next cycle.
584→                    // TODO: Add full re-fetch+merge+retry for parent mkdir publish (v2).
585→                    let parent_req = cipherbox_api_client::IpnsPublishRequest {
586→                        ipns_name: parent_ipns_name.clone(),
587→                        record: parent_record_b64,
588→                        metadata_cid: parent_meta_cid,
589→                        encrypted_ipns_private_key: None,
590→                        key_epoch: None,
591→                        expected_sequence_number: Some(seq.to_string()),
592→                    };
593→                    match cipherbox_api_client::ipns::publish_ipns(&api, &parent_req).await.map_err(|e| format!("{}", e))? {
594→                        cipherbox_api_client::PublishResult::Success => {
595→                            coordinator.record_publish(&parent_ipns_name, new_seq);
596→                            // Only unpin old CID on successful publish
597→                            if let Some(old) = parent_old_cid {
598→                                let _ = cipherbox_api_client::ipfs::unpin_content(&api, &old).await;
599→                            }
600→                            log::info!("Parent metadata published after mkdir");
601→                        }
602→                        cipherbox_api_client::PublishResult::Conflict { current_sequence_number } => {
603→                            log::warn!(
604→                                "Conflict on parent publish after mkdir (expected seq {}, server has {}). \
605→                                Debounced publish will retry.",
606→                                seq, current_sequence_number
607→                            );
608→                            // Do not record_publish or unpin -- let the next debounced publish pick up fresh seq
609→                        }
610→                    }
611→                    Ok::<(), String>(())
612→                });
613→
614→                if let Err(e) = result {
615→                    log::error!("Background mkdir publish failed: {}", e);
616→                }
617→            });
618→
619→            Ok(fuse_attr)
620→        })();
621→
622→        match result {
623→            Ok(fuse_attr) => {
624→                reply.entry(&DIR_TTL, &fuse_attr, 0);
625→            }
626→            Err(e) => {
627→                log::error!("mkdir failed: {}", e);
628→                reply.error(libc::EIO);
629→            }
630→        }
631→    }
632→
633→    /// Remove an empty directory.
634→    pub fn handle_rmdir(
635→        fs: &mut CipherBoxFS,
636→        parent: u64,
637→        name: &OsStr,
638→        reply: ReplyEmpty,
639→    ) {
640→        let name_str = match name.to_str() {
641→            Some(n) => n,
642→            None => {
643→                reply.error(libc::ENOENT);
644→                return;
645→            }
646→        };
647→
648→        let child_ino = match fs.inodes.find_child(parent, name_str) {
649→            Some(ino) => ino,
650→            None => {
651→                reply.error(libc::ENOENT);
652→                return;
653→            }
654→        };
655→
656→        // Capture folder data for bin entry before inode removal
657→        let bin_entry_data = match fs.inodes.get(child_ino) {
658→            Some(inode) => {
659→                match &inode.kind {
660→                    InodeKind::Folder {
661→                        ipns_name,
662→                        encrypted_folder_key,
663→                        ipns_private_key,
664→                        ..
665→                    } => {
666→                        // Check for non-empty folder (POSIX requirement)
667→                        if let Some(ref children) = inode.children {
668→                            if !children.is_empty() {
669→                                reply.error(libc::ENOTEMPTY);
670→                                return;
671→                            }
672→                        }
673→
674→                        let now_ms = SystemTime::now()
675→                            .duration_since(std::time::UNIX_EPOCH)
676→                            .unwrap_or_default()
677→                            .as_millis() as u64;
678→                        let created_ms = inode.attr.crtime
679→                            .duration_since(std::time::UNIX_EPOCH)
680→                            .unwrap_or_default()
681→                            .as_millis() as u64;
682→
683→                        // Build the ECIES-wrapped IPNS private key for the FolderEntry
684→                        let ipns_key_encrypted = match ipns_private_key {
685→                            Some(key) => match cipherbox_crypto::wrap_key(key, &fs.public_key) {
686→                                Ok(wrapped) => hex::encode(&wrapped),
687→                                Err(e) => {
688→                                    log::error!("rmdir: failed to wrap IPNS key for bin entry: {}", e);
689→                                    reply.error(libc::EIO);
690→                                    return;
691→                                }
692→                            },
693→                            None => {
694→                                log::error!("rmdir: missing folder IPNS private key for ino {}", child_ino);
695→                                reply.error(libc::EIO);
696→                                return;
697→                            }
698→                        };
699→
700→                        let folder_entry = cipherbox_core::folder::FolderEntry {
701→                            id: cipherbox_crypto::utils::generate_uuid_v4(),
702→                            name: inode.name.clone(),
703→                            ipns_name: ipns_name.clone(),
704→                            folder_key_encrypted: encrypted_folder_key.clone(),
705→                            ipns_private_key_encrypted: ipns_key_encrypted,
706→                            created_at: if created_ms > 0 { created_ms } else { now_ms },
707→                            modified_at: now_ms,
708→                        };
709→
710→                        Some((inode.name.clone(), folder_entry))
711→                    }
712→                    _ => {
713→                        reply.error(libc::ENOTDIR);
714→                        return;
715→                    }
716→                }
717→            }
718→            None => {
719→                reply.error(libc::ENOENT);
720→                return;
721→            }
722→        };
723→
724→        log::debug!("rmdir: {} from parent {}", name_str, parent);
725→
726→        let now = SystemTime::now();
727→
728→        fs.inodes.remove(child_ino);
729→
730→        if let Some(parent_inode) = fs.inodes.get_mut(parent) {
731→            parent_inode.attr.mtime = now;
732→            parent_inode.attr.ctime = now;
733→        }
734→
735→        if let Err(e) = fs.update_folder_metadata(parent) {
736→            log::error!("Failed to update folder metadata after rmdir: {}", e);
737→        }
738→
739→        // Create bin entry and publish to bin IPNS (fire-and-forget)
740→        if let Some((item_name, folder_entry)) = bin_entry_data {
741→            let parent_ipns_name = fs.inodes.get(parent)
742→                .map(|p| match &p.kind {
743→                    InodeKind::Root { ipns_name, .. } => ipns_name.clone().unwrap_or_default(),
744→                    InodeKind::Folder { ipns_name, .. } => ipns_name.clone(),
745→                    _ => String::new(),
746→                })
747→                .unwrap_or_default();
748→
749→            if parent_ipns_name.is_empty() {
750→                log::warn!(
751→                    "rmdir: missing parent IPNS name for parent ino {}, skipping bin publish",
752→                    parent
753→                );
754→            } else {
755→                let parent_path = crate::helpers::build_folder_path(fs, parent);
756→
757→                let bin_entry = cipherbox_core::bin::BinEntry {
758→                    id: cipherbox_crypto::utils::generate_uuid_v4(),
759→                    item_type: cipherbox_core::bin::BinItemType::Folder,
760→                    name: item_name,
761→                    original_parent_ipns_name: parent_ipns_name,
762→                    original_path: parent_path,
763→                    deleted_at: now
764→                        .duration_since(std::time::UNIX_EPOCH)
765→                        .unwrap_or_default()
766→                        .as_millis() as u64,
767→                    size: 0,
768→                    mime_type: String::new(),
769→                    content_cid: None,
770→                    content_size: None,
771→                    version_cids: None,
772→                    file_pointer: None,
773→                    folder_entry: Some(folder_entry),
774→                };
775→
776→                crate::spawn_bin_entry_publish(
777→                    fs.api.clone(),
778→                    fs.rt.clone(),
779→                    bin_entry,
780→                    fs.private_key.clone(),
781→                    fs.public_key.to_vec(),
782→                    fs.publish_coordinator.clone(),
783→                );
784→            }
785→        }
786→
787→        reply.ok();
788→    }
