  1→//! Authentication commands: login, session restore, silent refresh, logout.
  2→
  3→use tauri::{Manager, State};
  4→use zeroize::Zeroizing;
  5→
  6→use crate::keychain;
  7→use cipherbox_api_client;
  8→use crate::state::AppState;
  9→
 10→use super::util::{derive_public_key, extract_user_id_from_jwt};
 11→use super::vault::{fetch_and_decrypt_vault, initialize_vault};
 12→
 13→/// Handle completed Web3Auth authentication from the webview.
 14→///
 15→/// Called after the webview has completed the Web3Auth SDK flow and obtained
 16→/// an idToken and the user's secp256k1 private key. This command:
 17→/// 1. Sends idToken to backend to get access + refresh tokens
 18→/// 2. Stores refresh token in macOS Keychain
 19→/// 3. Stores private key and derived public key in AppState (memory only)
 20→/// 4. Fetches and decrypts vault keys (including root IPNS keypair)
 21→#[tauri::command]
 22→pub async fn handle_auth_complete(
 23→    app: tauri::AppHandle,
 24→    state: State<'_, AppState>,
 25→    id_token: String,
 26→    private_key: String,
 27→) -> Result<(), String> {
 28→    log::info!("Handling auth completion from webview");
 29→
 30→    // Update tray status: Mounting (auth in progress, about to mount)
 31→    let _ = crate::tray::update_tray_status(&app, &crate::tray::TrayStatus::Mounting);
 32→
 33→    // 1. Convert private key from hex to bytes and derive public key
 34→    //    (needed for the login request)
 35→    let private_key_hex = if private_key.starts_with("0x") {
 36→        &private_key[2..]
 37→    } else {
 38→        &private_key
 39→    };
 40→    let private_key_bytes =
 41→        hex::decode(private_key_hex).map_err(|_| "Invalid private key hex".to_string())?;
 42→    if private_key_bytes.len() != 32 {
 43→        return Err("Private key must be 32 bytes".to_string());
 44→    }
 45→
 46→    // Derive uncompressed public key from private key (65 bytes, 0x04 prefix)
 47→    // Used for both ECIES operations and backend auth (backend expects uncompressed)
 48→    let public_key_bytes = derive_public_key(&private_key_bytes)?;
 49→    let public_key_hex = hex::encode(&public_key_bytes); // 130 hex chars
 50→
 51→    // 2. Login with backend (requires uncompressed publicKey, 130 hex chars)
 52→    let login_req = cipherbox_api_client::LoginRequest {
 53→        id_token: id_token.clone(),
 54→        public_key: public_key_hex,
 55→        login_type: "corekit".to_string(),
 56→    };
 57→
 58→    let resp = state
 59→        .sdk
 60→        .api
 61→        .post("/auth/login", &login_req)
 62→        .await
 63→        .map_err(|e| format!("Login request failed: {}", e))?;
 64→
 65→    if !resp.status().is_success() {
 66→        let status = resp.status();
 67→        let body = resp.text().await.unwrap_or_default();
 68→        return Err(format!("Login failed ({}): {}", status, body));
 69→    }
 70→
 71→    let login_resp: cipherbox_api_client::LoginResponse = resp
 72→        .json()
 73→        .await
 74→        .map_err(|e| format!("Failed to parse login response: {}", e))?;
 75→
 76→    // Delegate to shared post-auth setup
 77→    complete_auth_setup(
 78→        &app,
 79→        &state,
 80→        login_resp.access_token,
 81→        login_resp.refresh_token,
 82→        Zeroizing::new(private_key_bytes),
 83→        public_key_bytes,
 84→        login_resp.is_new_user,
 85→        false,
 86→    )
 87→    .await
 88→}
 89→
 90→/// Shared post-auth setup used by both `handle_auth_complete` and `handle_test_login_complete`.
 91→///
 92→/// Stores tokens and keys, initializes/fetches vault, registers device, mounts FUSE,
 93→/// and hides the login window.
 94→pub(crate) async fn complete_auth_setup(
 95→    app: &tauri::AppHandle,
 96→    state: &AppState,
 97→    access_token: String,
 98→    refresh_token: String,
 99→    private_key_bytes: Zeroizing<Vec<u8>>,
100→    public_key_bytes: Vec<u8>,
101→    is_new_user: bool,
102→    skip_keychain: bool,
103→) -> Result<(), String> {
104→    // 1. Store access token in API client
105→    state.sdk.api.set_access_token(access_token.clone()).await;
106→
107→    // 2. Extract user ID from JWT claims (decode payload, read `sub`)
108→    let user_id = extract_user_id_from_jwt(&access_token)?;
109→    *state.sdk.user_id.write().await = Some(user_id.clone());
110→
111→    // 3. Store refresh token in Keychain (skip in test-login mode to avoid popups)
112→    if !skip_keychain {
113→        keychain::store_refresh_token(&user_id, &refresh_token)
114→            .map_err(|e| format!("Keychain store failed: {}", e))?;
115→        keychain::store_user_id(&user_id)
116→            .map_err(|e| format!("Keychain store user ID failed: {}", e))?;
117→    } else {
118→        log::info!("Skipping Keychain storage (test-login mode)");
119→    }
120→
121→    // 4. Store keys in SDK state
122→    *state.sdk.private_key.write().await = Some(private_key_bytes.to_vec());
123→    *state.sdk.public_key.write().await = Some(public_key_bytes.clone());
124→
125→    // 5. Initialize vault for new users, or fetch existing vault
126→    //    Also handle the edge case where user exists but vault was deleted.
127→    if is_new_user {
128→        log::info!("New user detected, initializing vault");
129→        initialize_vault(state, &public_key_bytes).await?;
130→    }
131→    match fetch_and_decrypt_vault(state).await {
132→        Ok(()) => {}
133→        Err(e) if e.contains("404") && !is_new_user => {
134→            log::warn!("Vault not found for existing user, re-initializing");
135→            initialize_vault(state, &public_key_bytes).await?;
136→            fetch_and_decrypt_vault(state).await?;
137→        }
138→        Err(e) => return Err(e),
139→    }
140→
141→    // 6. Mark as authenticated
142→    *state.sdk.is_authenticated.write().await = true;
143→
144→    // 7. Mount filesystem (or just mark as synced if no filesystem feature enabled)
145→    // NOTE: Device registry spawn moved AFTER mount to avoid concurrent HTTP
146→    //       requests that cause reqwest connection pool starvation during pre-populate.
147→    #[cfg(not(any(feature = "fuse", feature = "winfsp")))]
148→    {
149→        let _ = crate::tray::update_tray_status(app, &crate::tray::TrayStatus::Synced);
150→    }
151→    #[cfg(any(feature = "fuse", feature = "winfsp"))]
152→    {
153→        *state.mount_status.write().await = crate::state::MountStatus::Mounting;
154→        let private_key = state
155→            .sdk
156→            .private_key
157→            .read()
158→            .await
159→            .as_ref()
160→            .ok_or("Private key not available for filesystem mount")?
161→            .clone();
162→        let public_key = state
163→            .sdk
164→            .public_key
165→            .read()
166→            .await
167→            .as_ref()
168→            .ok_or("Public key not available for filesystem mount")?
169→            .clone();
170→        let root_folder_key = state
171→            .sdk
172→            .root_folder_key
173→            .read()
174→            .await
175→            .as_ref()
176→            .ok_or("Root folder key not available for filesystem mount")?
177→            .clone();
178→        let root_ipns_name = state
179→            .sdk
180→            .root_ipns_name
181→            .read()
182→            .await
183→            .as_ref()
184→            .ok_or("Root IPNS name not available for filesystem mount")?
185→            .clone();
186→        let root_ipns_private_key = state.sdk.root_ipns_private_key.read().await.clone();
187→
188→        // Extract TEE keys for new folder creation
189→        let tee_keys = state.sdk.tee_keys.read().await;
190→        let tee_public_key = tee_keys.as_ref().and_then(|tk| {
191→            hex::decode(&tk.current_public_key).ok()
192→        });
193→        let tee_key_epoch = tee_keys.as_ref().map(|tk| tk.current_epoch);
194→        drop(tee_keys);
195→
196→        let rt = tokio::runtime::Handle::current();
197→        match crate::fuse::mount_filesystem(
198→            state,
199→            rt,
200→            private_key,
201→            public_key,
202→            root_folder_key,
203→            root_ipns_name,
204→            root_ipns_private_key,
205→            tee_public_key,
206→            tee_key_epoch,
207→        ).await {
208→            Ok(_handle) => {
209→                *state.mount_status.write().await = crate::state::MountStatus::Mounted;
210→                let _ = crate::tray::update_tray_status(app, &crate::tray::TrayStatus::Synced);
211→                log::info!("Filesystem mounted at {}", crate::fuse::mount_point().display());
212→            }
213→            Err(e) => {
214→                let err_msg = format!("Filesystem mount failed: {}", e);
215→                *state.mount_status.write().await =
216→                    crate::state::MountStatus::Error(err_msg.clone());
217→                let _ = crate::tray::update_tray_status(
218→                    app,
219→                    &crate::tray::TrayStatus::Error(err_msg.clone()),
220→                );
221→                log::error!("{}", err_msg);
222→                // Don't fail auth -- user is authenticated but mount failed
223→            }
224→        }
225→    }
226→
227→    // 8. Register device in encrypted registry (non-blocking, after mount)
228→    {
229→        let reg_api = state.sdk.api.clone();
230→        let reg_private_key = Zeroizing::new(private_key_bytes.to_vec());
231→        let reg_public_key = public_key_bytes.clone();
232→        let reg_user_id = user_id.clone();
233→        tokio::spawn(async move {
234→            let pk_arr: [u8; 32] = match reg_private_key.as_slice().try_into() {
235→                Ok(arr) => arr,
236→                Err(_) => {
237→                    log::warn!("Device registry: invalid private key length");
238→                    return;
239→                }
240→            };
241→            match crate::registry::register_device(
242→                &reg_api,
243→                &pk_arr,
244→                &reg_public_key,
245→                &reg_user_id,
246→            )
247→            .await
248→            {
249→                Ok(()) => log::info!("Device registry updated"),
250→                Err(e) => log::warn!("Device registry update failed (non-blocking): {}", e),
251→            }
252→        });
253→    }
254→
255→    // Close OAuth popup windows and hide the login webview
256→    for (label, window) in app.webview_windows() {
257→        if label.starts_with("oauth-popup-") {
258→            let _ = window.destroy();
259→        } else if label == "main" {
260→            let _ = window.hide();
261→        }
262→    }
263→
264→    log::info!("Authentication complete for user {}", user_id);
265→    Ok(())
266→}
267→
268→/// Handle session restore when Core Kit has a restored LOGGED_IN session.
269→///
270→/// Called when Core Kit's init() restores a previous session from localStorage
271→/// and the Rust side already has a valid access token from silent refresh.
272→/// Unlike `handle_auth_complete`, this skips the `/auth/login` POST since
273→/// tokens are already valid.
274→#[tauri::command]
275→pub async fn handle_session_restore(
276→    app: tauri::AppHandle,
277→    state: State<'_, AppState>,
278→    private_key: String,
279→) -> Result<(), String> {
280→    log::info!("Handling session restore from Core Kit");
281→
282→    let _ = crate::tray::update_tray_status(&app, &crate::tray::TrayStatus::Mounting);
283→
284→    // Convert private key from hex to bytes
285→    let private_key_hex = if private_key.starts_with("0x") {
286→        &private_key[2..]
287→    } else {
288→        &private_key
289→    };
290→    let private_key_bytes =
291→        hex::decode(private_key_hex).map_err(|_| "Invalid private key hex".to_string())?;
292→    if private_key_bytes.len() != 32 {
293→        return Err("Private key must be 32 bytes".to_string());
294→    }
295→
296→    let public_key_bytes = derive_public_key(&private_key_bytes)?;
297→
298→    // Get the existing access token (set by try_silent_refresh)
299→    let access_token = state
300→        .sdk
301→        .api
302→        .get_access_token()
303→        .await
304→        .ok_or("No access token available - silent refresh may not have succeeded")?;
305→
306→    // Extract user_id from the existing access token to look up the refresh token
307→    let user_id = extract_user_id_from_jwt(&access_token)?;
308→    let refresh_token = keychain::get_refresh_token(&user_id)
309→        .map_err(|e| format!("Keychain read failed: {}", e))?
310→        .ok_or("No refresh token in Keychain")?;
311→
312→    complete_auth_setup(
313→        &app,
314→        &state,
315→        access_token,
316→        refresh_token,
317→        Zeroizing::new(private_key_bytes),
318→        public_key_bytes,
319→        false, // not a new user
320→        true,  // skip Keychain writes (already stored)
321→    )
322→    .await
323→}
324→
325→/// Try to silently refresh the session from a Keychain-stored refresh token.
326→///
327→/// On cold start, the private key is NOT available (it requires Web3Auth login).
328→/// This command refreshes the API session tokens only. The webview still needs
329→/// to complete Web3Auth login to obtain the private key for vault decryption.
330→///
331→/// Returns `true` if the API session was refreshed successfully.
332→/// Returns `false` if no stored session exists or refresh failed.
333→#[tauri::command]
334→pub async fn try_silent_refresh(state: State<'_, AppState>) -> Result<bool, String> {
335→    log::info!("Attempting silent refresh from Keychain");
336→
337→    // Check for stored user ID
338→    let user_id = match keychain::get_last_user_id() {
339→        Ok(Some(id)) => id,
340→        Ok(None) => {
341→            log::info!("No stored user ID, silent refresh skipped");
342→            return Ok(false);
343→        }
344→        Err(e) => {
345→            log::warn!("Failed to read user ID from Keychain: {}", e);
346→            return Ok(false);
347→        }
348→    };
349→
350→    // Get refresh token from Keychain
351→    let refresh_token = match keychain::get_refresh_token(&user_id) {
352→        Ok(Some(token)) => token,
353→        Ok(None) => {
354→            log::info!("No stored refresh token for user {}", user_id);
355→            return Ok(false);
356→        }
357→        Err(e) => {
358→            log::warn!("Failed to read refresh token from Keychain: {}", e);
359→            return Ok(false);
360→        }
361→    };
362→
363→    // POST /auth/refresh with the stored refresh token
364→    let refresh_req = cipherbox_api_client::RefreshRequest {
365→        refresh_token: refresh_token.clone(),
366→    };
367→
368→    let resp = match state.sdk.api.post("/auth/refresh", &refresh_req).await {
369→        Ok(r) => r,
370→        Err(e) => {
371→            log::warn!("Refresh request failed (network error): {}", e);
372→            return Ok(false);
373→        }
374→    };
375→
376→    if resp.status().as_u16() == 401 {
377→        // Stale token -- delete from Keychain
378→        log::info!("Refresh token expired, clearing Keychain");
379→        let _ = keychain::delete_refresh_token(&user_id);
380→        return Ok(false);
381→    }
382→
383→    if !resp.status().is_success() {
384→        log::warn!("Refresh failed with status {}", resp.status());
385→        return Ok(false);
386→    }
387→
388→    let refresh_resp: cipherbox_api_client::RefreshResponse = resp
389→        .json()
390→        .await
391→        .map_err(|e| format!("Failed to parse refresh response: {}", e))?;
392→
393→    // Store new tokens
394→    state.sdk.api.set_access_token(refresh_resp.access_token).await;
395→    keychain::store_refresh_token(&user_id, &refresh_resp.refresh_token)
396→        .map_err(|e| format!("Keychain store failed: {}", e))?;
397→    *state.sdk.user_id.write().await = Some(user_id.clone());
398→
399→    log::info!("Silent refresh successful for user {}", user_id);
400→
401→    // NOTE: Private key is NOT restored by silent refresh.
402→    // The webview must complete Web3Auth login to get the private key.
403→    // is_authenticated remains false until handle_auth_complete is called.
404→    Ok(true)
405→}
406→
407→/// Logout: invalidate session, clear Keychain, zero all sensitive keys.
408→#[tauri::command]
409→pub async fn logout(app: tauri::AppHandle, state: State<'_, AppState>) -> Result<(), String> {
410→    log::info!("Logging out");
411→
412→    // Unmount filesystem before clearing keys
413→    #[cfg(any(feature = "fuse", feature = "winfsp"))]
414→    {
415→        if let Err(e) = crate::fuse::unmount_filesystem() {
416→            log::warn!("Filesystem unmount failed (will continue logout): {}", e);
417→        }
418→        *state.mount_status.write().await = crate::state::MountStatus::Unmounted;
419→    }
420→
421→    // POST /auth/logout (best-effort, don't fail logout if server unreachable)
422→    let resp = state.sdk.api.authenticated_post("/auth/logout", &()).await;
423→    if let Err(e) = resp {
424→        log::warn!("Logout request failed (will continue local cleanup): {}", e);
425→    }
426→
427→    // Delete refresh token from Keychain
428→    if let Some(ref user_id) = *state.sdk.user_id.read().await {
429→        let _ = keychain::delete_refresh_token(user_id);
430→    }
431→
432→    // Zero all sensitive keys in memory
433→    state.clear_keys().await;
434→
435→    // Update tray status
436→    let _ = crate::tray::update_tray_status(&app, &crate::tray::TrayStatus::NotConnected);
437→
438→    log::info!("Logout complete");
439→    Ok(())
440→}
