/// Helper: Fetch, decrypt, and populate a folder's children (blocking).
pub fn fetch_and_populate_folder(
    fs: &mut CipherBoxFS,
    ino: u64,
    ipns_name: &str,
    folder_key: &[u8],
) -> Result<(), String> {
    let api = fs.api.clone();
    let ipns_name_owned = ipns_name.to_string();
    let folder_key_owned = folder_key.to_vec();
    let private_key = fs.private_key.clone();
    let rt = fs.rt.clone();

    let result = crate::block_with_timeout(&rt, async {
        let resolve_resp =
            cipherbox_api_client::ipns::resolve_ipns(&api, &ipns_name_owned).await.map_err(|e| e.to_string())?;
        let encrypted_bytes =
            cipherbox_api_client::ipfs::fetch_content(&api, &resolve_resp.cid).await.map_err(|e| e.to_string())?;
        Ok::<(Vec<u8>, String), String>((encrypted_bytes, resolve_resp.cid))
    })?;

    let (encrypted_bytes, cid) = result;
    let metadata =
        cipherbox_core::decrypt::decrypt_metadata_from_ipfs_public(&encrypted_bytes, &folder_key_owned)?;
    fs.metadata_cache
        .set(&ipns_name.to_string(), metadata.clone(), cid);
    fs.inodes.populate_folder(
        ino,
        &metadata,
        &private_key,
        &fs.public_key,
        false,
    )?;

    // Resolve unresolved FilePointers eagerly
    let unresolved = fs.inodes.get_unresolved_file_pointers();
    if !unresolved.is_empty() {
        log::info!(
            "Resolving {} FilePointer(s) for folder ino {}",
            unresolved.len(),
            ino
        );
        resolve_file_pointers_blocking(fs, &unresolved, &folder_key_owned)?;
    }

    Ok(())
}

