 1→//! AES-256-GCM encryption/decryption.
 2→//!
 3→//! Sealed format: IV (12 bytes) || Ciphertext || Auth Tag (16 bytes)
 4→//! This matches the TypeScript `sealAesGcm` output exactly.
 5→
 6→use aes_gcm::{
 7→    aead::{Aead, KeyInit},
 8→    Aes256Gcm, Nonce,
 9→};
10→
11→use crate::error::CryptoError;
12→use crate::utils::generate_iv;
13→
14→/// AES-256-GCM key size in bytes (256 bits).
15→pub const AES_KEY_SIZE: usize = 32;
16→
17→/// AES-GCM IV size in bytes (96 bits).
18→pub const AES_IV_SIZE: usize = 12;
19→
20→/// AES-GCM authentication tag size in bytes (128 bits).
21→pub const AES_TAG_SIZE: usize = 16;
22→
23→/// Minimum sealed data size: IV + auth tag (empty plaintext).
24→const MIN_SEALED_SIZE: usize = AES_IV_SIZE + AES_TAG_SIZE;
25→
26→/// Encrypt data using AES-256-GCM.
27→///
28→/// Returns ciphertext with 16-byte auth tag appended (same as Web Crypto API).
29→pub fn encrypt_aes_gcm(
30→    plaintext: &[u8],
31→    key: &[u8; 32],
32→    iv: &[u8; 12],
33→) -> Result<Vec<u8>, CryptoError> {
34→    let cipher = Aes256Gcm::new_from_slice(key).map_err(|_| CryptoError::AesEncryptionFailed)?;
35→    let nonce = Nonce::from_slice(iv);
36→
37→    cipher
38→        .encrypt(nonce, plaintext)
39→        .map_err(|_| CryptoError::AesEncryptionFailed)
40→}
41→
42→/// Decrypt data using AES-256-GCM.
43→///
44→/// Expects ciphertext with 16-byte auth tag appended.
45→pub fn decrypt_aes_gcm(
46→    ciphertext: &[u8],
47→    key: &[u8; 32],
48→    iv: &[u8; 12],
49→) -> Result<Vec<u8>, CryptoError> {
50→    let cipher = Aes256Gcm::new_from_slice(key).map_err(|_| CryptoError::AesDecryptionFailed)?;
51→    let nonce = Nonce::from_slice(iv);
52→
53→    cipher
54→        .decrypt(nonce, ciphertext)
55→        .map_err(|_| CryptoError::AesDecryptionFailed)
56→}
57→
58→/// Seal data using AES-256-GCM with automatic IV generation.
59→///
60→/// Returns: IV (12 bytes) || Ciphertext || Auth Tag (16 bytes)
61→/// This format matches the TypeScript `sealAesGcm` exactly.
62→pub fn seal_aes_gcm(plaintext: &[u8], key: &[u8; 32]) -> Result<Vec<u8>, CryptoError> {
63→    let iv = generate_iv();
64→    let ciphertext = encrypt_aes_gcm(plaintext, key, &iv)?;
65→
66→    // IV || ciphertext (which already includes the tag)
67→    let mut sealed = Vec::with_capacity(AES_IV_SIZE + ciphertext.len());
68→    sealed.extend_from_slice(&iv);
69→    sealed.extend_from_slice(&ciphertext);
70→    Ok(sealed)
71→}
72→
73→/// Unseal data encrypted with `seal_aes_gcm`.
74→///
75→/// Extracts IV from first 12 bytes, decrypts remainder.
76→pub fn unseal_aes_gcm(sealed: &[u8], key: &[u8; 32]) -> Result<Vec<u8>, CryptoError> {
77→    if sealed.len() < MIN_SEALED_SIZE {
78→        return Err(CryptoError::AesDecryptionFailed);
79→    }
80→
81→    let iv: [u8; 12] = sealed[..AES_IV_SIZE]
82→        .try_into()
83→        .map_err(|_| CryptoError::AesDecryptionFailed)?;
84→    let ciphertext = &sealed[AES_IV_SIZE..];
85→
86→    decrypt_aes_gcm(ciphertext, key, &iv)
87→}
