 1→//! Shared decrypt functions for folder and file metadata.
 2→//! Used by CipherBoxFS::drain_refresh_completions() which is platform-agnostic.
 3→
 4→use crate::folder::{FolderMetadata, FileMetadata};
 5→
 6→/// Decrypt folder metadata from IPFS encrypted format.
 7→///
 8→/// All folder metadata (including root) uses v1 JSON `{"iv":"...","data":"..."}`.
 9→/// The v2 blob format is only used for the vault key blob (separate IPNS name).
10→pub fn decrypt_metadata_from_ipfs_public(
11→    encrypted_bytes: &[u8],
12→    folder_key: &[u8],
13→) -> Result<FolderMetadata, String> {
14→    let json_portion = encrypted_bytes;
15→
16→    #[derive(serde::Deserialize)]
17→    struct EncryptedFolderMetadata {
18→        iv: String,
19→        data: String,
20→    }
21→
22→    let encrypted: EncryptedFolderMetadata = serde_json::from_slice(json_portion)
23→        .map_err(|e| format!("Failed to parse encrypted metadata JSON: {}", e))?;
24→
25→    let iv_bytes =
26→        hex::decode(&encrypted.iv).map_err(|_| "Invalid metadata IV hex".to_string())?;
27→    if iv_bytes.len() != 12 {
28→        return Err(format!(
29→            "Invalid IV length: {} (expected 12)",
30→            iv_bytes.len()
31→        ));
32→    }
33→    let iv: [u8; 12] = iv_bytes.try_into().unwrap();
34→
35→    use base64::Engine;
36→    let ciphertext = base64::engine::general_purpose::STANDARD
37→        .decode(&encrypted.data)
38→        .map_err(|e| format!("Invalid metadata base64: {}", e))?;
39→
40→    let folder_key_arr: [u8; 32] = folder_key
41→        .try_into()
42→        .map_err(|_| "Invalid folder key length".to_string())?;
43→
44→    // Reconstruct sealed format: IV || ciphertext (includes tag)
45→    let mut sealed = Vec::with_capacity(12 + ciphertext.len());
46→    sealed.extend_from_slice(&iv);
47→    sealed.extend_from_slice(&ciphertext);
48→
49→    crate::folder::decrypt_folder_metadata(&sealed, &folder_key_arr)
50→        .map_err(|e| format!("Metadata decryption failed: {}", e))
51→}
52→
53→/// Decrypt file metadata from IPFS encrypted JSON format.
54→pub fn decrypt_file_metadata_from_ipfs_public(
55→    encrypted_bytes: &[u8],
56→    folder_key: &[u8; 32],
57→) -> Result<FileMetadata, String> {
58→    #[derive(serde::Deserialize)]
59→    struct EncryptedFolderMetadata {
60→        iv: String,
61→        data: String,
62→    }
63→
64→    let encrypted: EncryptedFolderMetadata = serde_json::from_slice(encrypted_bytes)
65→        .map_err(|e| format!("Failed to parse encrypted file metadata JSON: {}", e))?;
66→
67→    let iv_bytes = hex::decode(&encrypted.iv)
68→        .map_err(|_| "Invalid file metadata IV hex".to_string())?;
69→    if iv_bytes.len() != 12 {
70→        return Err(format!(
71→            "Invalid IV length: {} (expected 12)",
72→            iv_bytes.len()
73→        ));
74→    }
75→    let iv: [u8; 12] = iv_bytes.try_into().unwrap();
76→
77→    use base64::Engine;
78→    let ciphertext = base64::engine::general_purpose::STANDARD
79→        .decode(&encrypted.data)
80→        .map_err(|e| format!("Invalid file metadata base64: {}", e))?;

