162→/// Compute the V2 signature.
163→///
164→/// Per IPNS spec, V2 signature is over: "ipns-signature:" + cbor_data
165→fn compute_v2_signature(
166→    ed25519_private_key: &[u8; 32],
167→    cbor_data: &[u8],
168→) -> Result<Vec<u8>, IpnsError> {
169→    let mut data_to_sign = Vec::with_capacity(IPNS_SIGNATURE_PREFIX.len() + cbor_data.len());
170→    data_to_sign.extend_from_slice(IPNS_SIGNATURE_PREFIX);
171→    data_to_sign.extend_from_slice(cbor_data);
172→
173→    sign_ed25519(&data_to_sign, ed25519_private_key).map_err(|_| IpnsError::SigningFailed)
174→}
