+//! macOS-specific FUSE mount/unmount using FUSE-T with SMB backend.
+
+use crate::mount_point;
+
+/// Unmount the FUSE filesystem on macOS.
+///
+/// Calls `umount` first, then `diskutil unmount force` as fallback.
+pub fn unmount_filesystem() -> Result<(), String> {
+    let mount_path = mount_point();
+    log::info!("Unmounting CipherBoxFS at {}", mount_path.display());
+
+    // Clean up temp directory
+    let temp_dir = std::env::temp_dir().join("cipherbox");
+    if temp_dir.exists() {
+        if let Err(e) = std::fs::remove_dir_all(&temp_dir) {
+            log::warn!("Failed to clean temp directory: {}", e);
+        }
+    }
+
+    let status = std::process::Command::new("umount")
+        .arg(mount_path.to_str().unwrap())
+        .status()
+        .map_err(|e| format!("Failed to run umount: {}", e))?;
+
+    if status.success() {
+        log::info!("FUSE filesystem unmounted successfully");
+        Ok(())
+    } else {
+        log::info!("umount failed (likely busy), trying diskutil unmount force");
+        let status = std::process::Command::new("diskutil")
+            .args(["unmount", "force", mount_path.to_str().unwrap()])
+            .status()
+            .map_err(|e| format!("Failed to run diskutil unmount force: {}", e))?;","path":"crates/fuse/src/platform/macos.rs","commit_id":"50187b2b13b6c43cb205ee176ff0eff0e09191e7","original_commit_id":"399612966e07bba182f9f7c73bbb1e2326308d14","user":{"login":"FSM1","id":12774278,"node_id":"MDQ6VXNlcjEyNzc0Mjc4","avatar_url":"https://avatars.githubusercontent.com/u/12774278?v=4","gravatar_id":"","url":"https://api.github.com/users/FSM1","html_url":"https://github.com/FSM1","followers_url":"https://api.github.com/users/FSM1/followers","following_url":"https://api.github.com/users/FSM1/following{/other_user}","gists_url":"https://api.github.com/users/FSM1/gists{/gist_id}","starred_url":"https://api.github.com/users/FSM1/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/FSM1/subscriptions","organizations_url":"https://api.github.com/users/FSM1/orgs","repos_url":"https://api.github.com/users/FSM1/repos","events_url":"https://api.github.com/users/FSM1/events{/privacy}","received_events_url":"https://api.github.com/users/FSM1/received_events","type":"User","user_view_type":"public","site_admin":false},"body":"Fixed in same commit (50187b2b1) — `diskutil` args now use `.arg(&mount_path)` instead of `.to_str().unwrap()`.","created_at":"2026-03-24T19:04:05Z","updated_at":"2026-03-24T19:04:05Z","html_url":"https://github.com/FSM1/cipher-box/pull/352#discussion_r2983700572","pull_request_url":"https://api.github.com/repos/FSM1/cipher-box/pulls/352","_links":{"self":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2983700572"},"html":{"href":"https://github.com/FSM1/cipher-box/pull/352#discussion_r2983700572"},"pull_request":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/352"}},"reactions":{"url":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2983700572/reactions","total_count":0,"+1":0,"-1":0,"laugh":0,"hooray":0,"confused":0,"heart":0,"rocket":0,"eyes":0},"start_line":30,"original_start_line":30,"start_