quest":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/352"}},"reactions":{"url":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2983701636/reactions","total_count":0,"+1":0,"-1":0,"laugh":0,"hooray":0,"confused":0,"heart":0,"rocket":0,"eyes":0},"start_line":14,"original_start_line":14,"start_side":"RIGHT","line":15,"original_line":15,"side":"RIGHT","in_reply_to_id":2982250830,"author_association":"OWNER","original_position":15,"position":15,"subject_type":"line"}{"url":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2983701712","pull_request_review_id":4001631075,"id":2983701712,"node_id":"PRRC_kwDOQ6DXvM6x16zQ","diff_hunk":"@@ -0,0 +1,106 @@
+//! ECIES key wrapping using secp256k1.
+//!
+//! Uses the `ecies` Rust crate which is cross-compatible with the `eciesjs` npm package
+//! (same author: ecies/rs and ecies/js). Format: ephemeral_pubkey(65) || nonce(16) || tag(16) || ciphertext.
+
+use crate::error::CryptoError;
+
+/// secp256k1 uncompressed public key size in bytes (04 prefix + x + y coordinates).
+pub const SECP256K1_PUBLIC_KEY_SIZE: usize = 65;
+
+/// secp256k1 private key size in bytes.
+pub const SECP256K1_PRIVATE_KEY_SIZE: usize = 32;
+
+/// ECIES minimum ciphertext size: ephemeral pubkey (65) + auth tag (16).
+pub const ECIES_MIN_CIPHERTEXT_SIZE: usize = SECP256K1_PUBLIC_KEY_SIZE + 16;
+
+/// Wrap (encrypt) data using ECIES with secp256k1.
+///
+/// The `ecies` Rust crate and `eciesjs` npm package produce compatible output.
+pub fn wrap_key(data: &[u8], recipient_public_key: &[u8]) -> Result<Vec<u8>, CryptoError> {
+    // Validate public key size (uncompressed secp256k1)
+    if recipient_public_key.len() != SECP256K1_PUBLIC_KEY_SIZE {
+        return Err(CryptoError::InvalidPublicKey);
+    }
+
+    // Validate uncompressed public key prefix (0x04)
+    if recipient_public_key[0] != 0x04 {
+        return Err(CryptoError::InvalidPublicKey);
+    }
+
+    ecies::encrypt(recipient_public_key, data).map_err(|_| CryptoError::EciesWrappingFailed)
+}
+
+/// Unwrap (decrypt) data using ECIES with secp256k1.
+pub fn unwrap_key(wrapped: &[u8], private_key: &[u8]) -> Result<Vec<u8>, CryptoError> {
+    // Validate private key size
+    if private_key.len() != SECP256K1_PRIVATE_KEY_SIZE {
+        return Err(CryptoError::InvalidPrivateKey);
+    }
+
+    // Validate minimum ciphertext size
+    if wrapped.len() < ECIES_MIN_CIPHERTEXT_SIZE {
+        return Err(CryptoError::EciesUnwrappingFailed);
+    }","path":"crates/crypto/src/ecies.rs","commit_id":"50187b2b13b6c43cb205ee176ff0eff0e09191e7","original_commit_id":"399612966e07bba182f9f7c73bbb1e2326308d14","user":{"login":"FSM1","id":12774278,"node_id":"MDQ6VXNlcjEyNzc0Mjc4","avatar_url":"https://avatars.githubusercontent.com/u/12774278?v=4","gravatar_id":"","url":"https://api.github.com/users/FSM1","html_url":"https://github.com/FSM1","followers_url":"https://api.github.com/users/FSM1/followers","following_url":"https://api.github.com/users/FSM1/following{/other_user}","gists_url":"https://api.github.com/users/FSM1/gists{/gist_id}","starred_url":"https://api.github.com/users/FSM1/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/FSM1/subscriptions","organizations_url":"https://api.github.com/users/FSM1/orgs","repos_url":"https://api.github.com/users/FSM1/repos","events_url":"https://api.github.com/users/FSM1/events{/privacy}","received_events_url":"https://api.github.com/users/FSM1/received_events","type":"User","user_view_type":"public","site_admin":false},"body":"Same reasoning as above — the `ecies::decrypt()` call is the authoritative validation. Our size check is a fast path for rejecting obviously bad input.","created_at":"2026-03-24T19:04:19Z","updated_at":"2026-03-24T19:04:19Z","html_url":"https://github.com/FSM1/cipher-box/pull/352#discussion_r2983701712","pull_request_url":"https://api.github.com/repos/FSM1/cipher-box/pulls/352","_links":{"self":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2983701712"},"html":{"href":"https://github.com/FSM1/cipher-box/pull/352#discussion_r2983701712"},"pull_request":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/352"}},"reactions":{"url":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2983701712/reactions","total_count":0,"+1":0,"-1":0,"laugh":0,"hooray":0,"confused":0,"heart":0,"rocket":0,"eyes":0},"start_line":41,"original_start_line":41,"start_side":"RIGHT","line":44,"original_line":44,"