//! CipherBox FUSE filesystem implementation.
//!
//! Platform-agnostic data structures (InodeTable, MetadataCache, ContentCache,
//! FileHandle) are shared across all platforms. Platform-specific mount/unmount
//! and FUSE callback implementations are behind feature flags.

pub mod inode;
pub mod cache;
pub mod file_handle;
pub mod helpers;
pub mod constants;
pub mod error;

// FUSE operations (macOS/Linux - fuser-based)
#[cfg(feature = "fuse")]
pub mod operations;
#[cfg(feature = "fuse")]
pub mod read_ops;
#[cfg(feature = "fuse")]
pub mod write_ops;
#[cfg(feature = "fuse")]
pub mod dir_ops;

// Platform-specific modules
pub mod platform;

// Re-exports
pub use inode::{InodeTable, InodeData};
pub use cache::{MetadataCache, ContentCache};
pub use file_handle::OpenFileHandle;
pub use error::FuseError;

// -- CipherBoxFS and supporting types (require filesystem feature) -----------

#[cfg(any(feature = "fuse", feature = "winfsp"))]

//! Platform-specific mount/unmount implementations.
//!
//! Each platform module provides mount and unmount functions gated behind
//! the appropriate feature flag.

#[cfg(all(feature = "fuse", target_os = "macos"))]
pub mod macos;

#[cfg(all(feature = "fuse", target_os = "linux"))]
pub mod linux;

#[cfg(feature = "winfsp")]
pub mod windows;

//! Windows WinFsp platform module for cipherbox-fuse.
//!
//! Contains all WinFsp operation implementations (FileSystemContext, read ops,
//! write ops, directory ops). Mount/unmount logic stays in the desktop app
//! since it depends on Tauri AppState.

#[cfg(feature = "winfsp")]
mod read_ops;
#[cfg(feature = "winfsp")]
mod write_ops;
#[cfg(feature = "winfsp")]
mod dir_ops;
#[cfg(feature = "winfsp")]
pub mod operations;

